-- Enable RLS on all tables
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- Helper function to check if current user is an editor of a specific team
create or replace function public.is_team_editor(target_team_id bigint)
returns boolean as $$
  select exists (
    select 1
    from public.team_members
    where team_id = target_team_id
      and user_id = auth.uid()
      and role = 'editor'
  );
$$ language sql security definer;

-- Helper function to check if current user is a member (viewer or editor) of a specific team
create or replace function public.is_team_member(target_team_id bigint)
returns boolean as $$
  select exists (
    select 1
    from public.team_members
    where team_id = target_team_id
      and user_id = auth.uid()
  );
$$ language sql security definer;

-- R1: Users can see the teams they belong to
create policy "users_see_own_teams"
on public.teams
for select
to authenticated
using (
  public.is_team_member(id)
);

-- R2: Users can see their own membership rows only
create policy "users_see_own_memberships"
on public.team_members
for select
to authenticated
using (
  user_id = auth.uid()
);

-- R7 (Teams): No create, update, delete for app users
create policy "no_team_modifications"
on public.teams
for all
to authenticated
using (false)
with check (false);

-- R7 (Memberships): No create, update, delete for app users
create policy "no_membership_modifications"
on public.team_members
for all
to authenticated
using (false)
with check (false);

-- R3: Members can read team documents, excluding deleted ones
create policy "members_read_team_documents"
on public.documents
for select
to authenticated
using (
  deleted_at is null
  and public.is_team_member(team_id)
);

-- R4: Editors can create documents in their teams
create policy "editors_create_documents"
on public.documents
for insert
to authenticated
with check (
  public.is_team_editor(team_id)
  and created_by = auth.uid()
);

-- R5: Editors can edit documents in their teams (ensure team membership remains valid)
create policy "editors_update_documents"
on public.documents
for update
to authenticated
using (
  public.is_team_editor(team_id)
  and deleted_at is null
)
with check (
  public.is_team_editor(team_id)
  and deleted_at is null
);

-- R6: Only creator can delete (soft delete by setting deleted_at)
create policy "creators_delete_documents"
on public.documents
for update
to authenticated
using (
  created_by = auth.uid()
  and deleted_at is null
)
with check (
  created_by = auth.uid()
  and deleted_at is not null
);

-- R8: Anonymous visitors cannot see or change anything (explicit deny, though default is deny)
create policy "deny_anon_teams"
on public.teams
for all
to anon
using (false)
with check (false);

create policy "deny_anon_members"
on public.team_members
for all
to anon
using (false)
with check (false);

create policy "deny_anon_documents"
on public.documents
for all
to anon
using (false)
with check (false);

-- Grants for authenticated users to interact with tables (policies handle row-level logic)
grant usage on schema public to authenticated;
grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update on public.documents to authenticated;

-- Revoke direct access from anon
revoke all on public.teams from anon;
revoke all on public.team_members from anon;
revoke all on public.documents from anon;
