```sql
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- Helper function to check if current user is a member of a team with a specific role
create or replace function public.is_team_member_with_role(p_team_id bigint, p_required_role text)
returns boolean as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = p_required_role
  );
$$ language sql security definer stable;

-- Helper function to check if current user is any member of a team
create or replace function public.is_team_member(p_team_id bigint)
returns boolean as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$ language sql security definer stable;

-- R1: Users can see the teams they belong to.
create policy "users_see_own_teams" on public.teams
  for select
  to authenticated
  using (public.is_team_member(id));

-- R2: Users can see their own membership rows, but not other people's.
create policy "users_see_own_memberships" on public.team_members
  for select
  to authenticated
  using (user_id = auth.uid());

-- R3: Members of a team can read the team's documents, except deleted documents.
create policy "members_read_team_documents" on public.documents
  for select
  to authenticated
  using (
    deleted_at is null
    and public.is_team_member(team_id)
  );

-- R4: Editors can create documents in their teams. Viewers cannot.
create policy "editors_create_documents" on public.documents
  for insert
  to authenticated
  with check (
    public.is_team_member_with_role(team_id, 'editor')
    and created_by = auth.uid()
  );

-- R5: Editors can edit any document in their teams.
create policy "editors_update_team_documents" on public.documents
  for update
  to authenticated
  using (
    deleted_at is null
    and public.is_team_member_with_role(team_id, 'editor')
  )
  with check (
    public.is_team_member_with_role(team_id, 'editor')
  );

-- R6: Only the person who created a document can delete it (soft delete by setting deleted_at).
create policy "creators_delete_documents" on public.documents
  for update
  to authenticated
  using (
    created_by = auth.uid()
    and deleted_at is null
  )
  with check (
    created_by = auth.uid()
    and deleted_at is not null
  );

-- R7: Teams and memberships cannot be created, changed or removed by users of the app.
-- Explicitly deny insert, update, delete for authenticated users on teams and team_members
create policy "no_user_insert_teams" on public.teams for insert to authenticated with check (false);
create policy "no_user_update_teams" on public.teams for update to authenticated using (false);
create policy "no_user_delete_teams" on public.teams for delete to authenticated using (false);

create policy "no_user_insert_members" on public.team_members for insert to authenticated with check (false);
create policy "no_user_update_members" on public.team_members for update to authenticated using (false);
create policy "no_user_delete_members" on public.team_members for delete to authenticated using (false);

-- R8: Anonymous visitors cannot see or change anything.
-- By default, no policies are created for 'anon' role, so they have no access.
-- Explicitly ensure no access by not granting anything to anon.

-- R9: Service role bypasses RLS automatically in Supabase, no policy needed.

-- Revoke default privileges to ensure anon has no access
revoke all on table public.teams from anon;
revoke all on table public.team_members from anon;
revoke all on table public.documents from anon;

-- Grant necessary permissions to authenticated role (policies control row access)
grant usage on schema public to authenticated;
grant select on table public.teams to authenticated;
grant select on table public.team_members to authenticated;
grant select, insert, update on table public.documents to authenticated;
```

