create or replace function public.is_org_admin(target_org_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.org_members
    where org_id = target_org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$ language sql security definer stable;

-- R1: Members can see membership rows of their own organizations only
create policy "org_members_select_own_org"
on public.org_members
for select
to authenticated
using (is_org_member(org_id));

-- R6: Memberships cannot be created, changed, or removed by app users
create policy "org_members_no_insert"
on public.org_members
for insert
to authenticated
with check (false);

create policy "org_members_no_update"
on public.org_members
for update
to authenticated
using (false);

create policy "org_members_no_delete"
on public.org_members
for delete
to authenticated
using (false);

-- R2: Members can see organizations they belong to
create policy "orgs_select_own"
on public.orgs
for select
to authenticated
using (is_org_member(id));

-- R2 & R3: Members can see projects of their orgs; Admins can insert/update/delete projects in their orgs
create policy "projects_select_own_org"
on public.projects
for select
to authenticated
using (is_org_member(org_id));

create policy "projects_admin_insert"
on public.projects
for insert
to authenticated
with check (is_org_admin(org_id));

create policy "projects_admin_update"
on public.projects
for update
to authenticated
using (is_org_admin(org_id));

create policy "projects_admin_delete"
on public.projects
for delete
to authenticated
using (is_org_admin(org_id));

-- R7: Anonymous visitors cannot see or change anything in public tables
