on storage.objects
for select
to authenticated
using (
  bucket_id = 'project-files'
  and exists (
    select 1
    from public.projects p
    where p.id = (storage.foldername(name))[1]::bigint
      and is_org_member(p.org_id)
  )
);

-- R4: Only admins can upload/delete project files
