on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'project-files'
  and exists (
    select 1
    from public.projects p
    where p.id = (storage.foldername(name))[1]::bigint
      and is_org_admin(p.org_id)
  )
);

create policy "project_files_delete"
on storage.objects
for delete
to authenticated
using (
  bucket_id = 'project-files'
  and exists (
    select 1
    from public.projects p
    where p.id = (storage.foldername(name))[1]::bigint
      and is_org_admin(p.org_id)
  )
);

-- R5: Anyone can view avatars
create policy "avatars_select_public"
on storage.objects
for select
to anon, authenticated
using (bucket_id = 'avatars');

-- R5: Signed-in users can upload avatars only to their own folder
create policy "avatars_insert_own"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'avatars'
  and (storage.foldername(name))[1] = auth.uid()::text
);

-- R5: Users can update/delete their own avatar files
create policy "avatars_update_own"
on storage.objects
for update
to authenticated
using (
  bucket_id = 'avatars'
  and (storage.foldername(name))[1] = auth.uid()::text
);

create policy "avatars_delete_own"
on storage.objects
for delete
to authenticated
using (
  bucket_id = 'avatars'
  and (storage.foldername(name))[1] = auth.uid()::text
);

-- Revoke direct access from anon to tables (already covered by policies, but explicit for clarity)
revoke all on table public.orgs from anon;
revoke all on table public.org_members from anon;
revoke all on table public.projects from anon;

