on public.orgs
for select
to authenticated
using (
  public.is_org_member(id)
);

-- R2 & R3: Members can see projects in their orgs; Admins can modify projects in their orgs
create policy "projects_select_own_org"
on public.projects
for select
to authenticated
using (
