grant execute on function public.is_org_admin(bigint) to authenticated;
grant execute on function public.is_org_member(bigint) to authenticated;

-- Revoke any unintended access to tables directly if previous grants existed (defensive, though RLS handles row level)
revoke all on table public.orgs from anon;
revoke all on table public.org_members from anon;
revoke all on table public.projects from anon;

grant select on table public.orgs to authenticated;
grant select on table public.org_members to authenticated;
grant select on table public.projects to authenticated;
grant insert, update, delete on table public.projects to authenticated; -- Controlled by RLS policy
grant insert, update, delete on table public.org_members to authenticated; -- Controlled by RLS policy (which denies)

-- Storage grants are handled via policies, but ensure bucket access basics
-- (Supabase usually handles role grants on storage.objects, policies restrict rows)
