  auth.role() = 'authenticated'
  and requester_id = auth.uid()
  and status = 'open'
  and assigned_agent is null
);

create policy "Agents can update any ticket"
on public.tickets for update
using (
  auth.role() = 'authenticated'
  and public.is_agent()
);

