-- R4 & R5: decide_expense function
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void as $$
declare
  v_expense record;
  v_is_manager boolean;
  v_caller_id uuid;
begin
  -- Determine caller ID (null for service_role as per R5 requirement to leave decided_by empty)
  if auth.role() = 'service_role' then
    v_caller_id := null;
  else
    v_caller_id := auth.uid();
  end if;

  -- Fetch expense details
  select * into v_expense from public.expenses where id = p_expense_id;

  -- Raise if not found
  if not found then
    raise exception 'Expense not found';
  end if;

  -- R5: Service role can act on any pending expense
  if auth.role() = 'service_role' then
    if v_expense.status != 'pending' then
      raise exception 'Expense is not pending';
    end if;
  else
    -- R4: Authenticated user checks
    -- Must be manager of the department
    v_is_manager := public.is_department_manager(v_expense.department_id, v_caller_id);
    if not v_is_manager then
      raise exception 'Caller is not a manager of this department';
    end if;

    -- Must be pending
    if v_expense.status != 'pending' then
      raise exception 'Expense is not pending';
    end if;

    -- Caller did not submit it
    if v_expense.submitted_by = v_caller_id then
      raise exception 'Managers cannot approve their own expenses';
    end if;
  end if;

  -- Perform update
  update public.expenses
  set
    status = case when p_approve then 'approved' else 'rejected' end,
    decided_by = v_caller_id
  where id = p_expense_id;
end;
$$ language plpgsql security definer;

-- Grants for authenticated users to use the function
grant execute on function public.decide_expense(bigint, boolean) to authenticated;

-- Ensure service_role has full access (usually default, but explicit for clarity in RLS context)
grant all on table public.departments to service_role;
grant all on table public.department_members to service_role;
