$$ language sql security definer stable;

-- R6 & R8: Departments are read-only for app users, full access for service_role
create policy "Allow service role full access to departments"
  on public.departments
  for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "Allow users to view departments they belong to or manage"
  on public.departments
  for select
  using (
    auth.role() = 'authenticated' AND (
      id IN (select department_id from public.department_members where user_id = auth.uid())
      OR
      exists (select 1 from public.department_members dm where dm.department_id = id and dm.user_id = auth.uid() and dm.is_manager = true)
    )
  );

-- R6 & R8: Memberships are read-only for app users, full access for service_role
create policy "Allow service role full access to department_members"
  on public.department_members
  for all
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "Allow users to see their own memberships"
  on public.department_members
  for select
  using (auth.role() = 'authenticated' AND user_id = auth.uid());

-- R1, R2, R3, R7, R8: Expenses Policies

-- R1: Select policy
create policy "Allow users to read expenses"
  on public.expenses
  for select
  using (
    auth.role() = 'authenticated' AND (
      submitted_by = auth.uid() -- Own expenses
      OR
      is_department_manager(department_id) -- Manager of the department
    )
  );

-- R2: Insert policy
create policy "Allow users to submit expenses"
  on public.expenses
  for insert
  with check (
    auth.role() = 'authenticated' AND
    submitted_by = auth.uid() AND
    status = 'pending' AND
    decided_by IS NULL AND
    exists (select 1 from public.department_members dm where dm.department_id = department_id and dm.user_id = auth.uid())
  );

-- R3: Update policy (only amount for own pending expenses)
-- Prevent direct updates to status/decided_by by only allowing specific columns in WITH CHECK if needed, 
-- but strictly enforcing logic via USING clause for visibility and application logic constraints.
-- Since SQL policies can't easily restrict *which* columns are updated without triggers for enforcement,
-- we rely on the USING clause to limit rows, and the requirement says "Nobody can change status... by updating directly".
-- We will add a trigger to enforce column restrictions for R3 strictly.
create policy "Allow users to update own pending expenses"
  on public.expenses
  for update
  using (
    auth.role() = 'authenticated' AND
    submitted_by = auth.uid() AND
    status = 'pending'
  );

-- R8: Service role bypass is implicit in Supabase, but explicit policies ensure clarity if needed. 
-- However, standard RLS behavior for service_role is bypass. We just ensure no restrictive policies block it.
-- The policies above use `auth.role() = 'authenticated'` which excludes service_role, but service_role bypasses RLS entirely.
-- To be safe and explicit about R8 (full access), we don't need extra policies as service_role bypasses RLS.
-- But to ensure R7 (Anonymous cannot see anything), the `auth.role() = 'authenticated'` check handles it.

-- Trigger to enforce R3: Prevent direct updates to status and decided_by
create or replace function public.enforce_expense_update_rules()
returns trigger as $$
begin
  if tg_op = 'UPDATE' then
    -- If not service_role, enforce restrictions
    if auth.role() != 'service_role' then
      if new.status != old.status then
        raise exception 'Direct update of status is not allowed';
      end if;
      if new.decided_by is distinct from old.decided_by then
        raise exception 'Direct update of decided_by is not allowed';
      end if;
      -- Ensure only amount can be changed (and technically other non-restricted cols if any, but schema only has amount mutable per R3)
      if new.amount != old.amount then
        -- Allowed
        null;
      end if;
      -- Check if any other column changed unexpectedly (defensive)
      if new.department_id != old.department_id or new.submitted_by != old.submitted_by then
         raise exception 'Cannot change department or submitter';
      end if;
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trg_enforce_expense_update_rules
  before update on public.expenses
  for each row
  execute function public.enforce_expense_update_rules();

-- R4 & R5: decide_expense function
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void as $$
declare
  v_expense record;
  v_is_manager boolean;
begin
  -- Fetch expense details
  select * into v_expense from public.expenses where id = p_expense_id;

  if not found then
    raise exception 'Expense not found';
  end if;

  -- R5: Service role logic
  if auth.role() = 'service_role' then
    if v_expense.status != 'pending' then
      raise exception 'Expense is not pending';
    end if;

    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = null -- Left empty for service role
    where id = p_expense_id;

    return;
  end if;

  -- R4: Authenticated user logic

  -- Check if caller is manager of the department
  select is_manager into v_is_manager
  from public.department_members
  where department_id = v_expense.department_id and user_id = auth.uid();

  if not v_is_manager then
    raise exception 'Caller is not a manager of this department';
  end if;

  -- Check if expense is pending
  if v_expense.status != 'pending' then
    raise exception 'Expense is not pending';
  end if;

  -- Check if caller submitted the expense
  if v_expense.submitted_by = auth.uid() then
    raise exception 'Managers cannot approve/reject their own expenses';
  end if;

  -- Perform update
  update public.expenses
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = auth.uid()
  where id = p_expense_id;

end;
$$ language plpgsql security definer;

