create function public.is_org_member(p_org_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.org_members
    where org_id = p_org_id
      and user_id = auth.uid()
  );
$$ language sql security definer stable;

create function public.is_only_owner(p_org_id bigint)
returns boolean as $$
  select count(*) = 1
  from public.org_members
  where org_id = p_org_id
    and role = 'owner';
$$ language sql security definer stable;

create function public.handle_new_org_owner()
returns trigger as $$
begin
  if not exists (
    select 1 from public.org_members
    where org_id = new.id and user_id = new.created_by
  ) then
    insert into public.org_members (org_id, user_id, role)
    values (new.id, new.created_by, 'owner');
  end if;
  return new;
end;
$$ language plpgsql security definer;

