  (user_id = auth.uid() and not (role = 'owner' and public.is_only_owner(org_id)))
  or
  (public.is_org_admin(org_id) and role = 'member' and user_id != auth.uid())
  or
  (public.is_org_owner(org_id) and role in ('admin', 'owner') and user_id != auth.uid())
);

