-- Enable RLS
alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.enrollments enable row level security;

-- Helper function to check if user is instructor of a course
create or replace function public.is_course_instructor(course_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.courses c
    where c.id = course_id and c.instructor_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check if user is enrolled in a course
create or replace function public.is_enrolled_in_course(course_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.enrollments e
    where e.course_id = course_id and e.student_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check if course is published
create or replace function public.is_course_published(course_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.courses c
    where c.id = course_id and c.is_published = true
  );
$$ language sql security definer;

-- COURSES POLICIES

-- R1: Anyone can read published courses; Instructors can read their own unpublished courses
create policy "courses_select_published_or_instructor" on public.courses
for select
using (
  is_published = true 
  or (auth.role() = 'authenticated' and instructor_id = auth.uid())
);

-- R2: Signed-in users can create courses as their instructor
create policy "courses_insert_authenticated" on public.courses
for insert
with check (
  auth.role() = 'authenticated' 
  and instructor_id = auth.uid()
);

-- R2: Instructors can update their own courses (cannot change instructor_id)
create policy "courses_update_instructor" on public.courses
for update
using (
  auth.role() = 'authenticated' 
  and instructor_id = auth.uid()
)
with check (
  auth.role() = 'authenticated' 
  and instructor_id = auth.uid()
);

-- R2: Instructors can delete their own courses
create policy "courses_delete_instructor" on public.courses
for delete
using (
  auth.role() = 'authenticated' 
  and instructor_id = auth.uid()
);

-- LESSONS POLICIES

-- R3: Anyone can read preview lessons of published courses
-- R3: Enrolled students can read all lessons of published courses they are enrolled in
-- R3: Instructors can read all lessons of their own courses
create policy "lessons_select_public_preview_or_enrolled_or_instructor" on public.lessons
for select
using (
  -- Case 1: Preview lesson in a published course (Anyone)
  (is_preview = true and public.is_course_published(course_id))
  -- Case 2: Enrolled student in a published course (Authenticated only via is_enrolled check requiring uid)
  or (auth.role() = 'authenticated' and public.is_course_published(course_id) and public.is_enrolled_in_course(course_id))
  -- Case 3: Instructor of the course
  or (auth.role() = 'authenticated' and public.is_course_instructor(course_id))
);

-- R3: Instructors can create lessons for their own courses
create policy "lessons_insert_instructor" on public.lessons
for insert
with check (
  auth.role() = 'authenticated' 
  and public.is_course_instructor(course_id)
);

-- R3: Instructors can update lessons for their own courses
create policy "lessons_update_instructor" on public.lessons
for update
using (
  auth.role() = 'authenticated' 
  and public.is_course_instructor(course_id)
)
with check (
  auth.role() = 'authenticated' 
  and public.is_course_instructor(course_id)
);

-- R3: Instructors can delete lessons for their own courses
create policy "lessons_delete_instructor" on public.lessons
for delete
using (
  auth.role() = 'authenticated' 
  and public.is_course_instructor(course_id)
);

-- ENROLLMENTS POLICIES

-- R4: Signed-in users can enroll themselves in published courses
-- R4: Cannot enroll someone else (student_id must match auth.uid)
create policy "enrollments_insert_self_published" on public.enrollments
for insert
with check (
  auth.role() = 'authenticated'
  and student_id = auth.uid()
  and public.is_course_published(course_id)
);

-- R4: Signed-in users can remove their own enrollments
create policy "enrollments_delete_self" on public.enrollments
for delete
using (
  auth.role() = 'authenticated'
  and student_id = auth.uid()
);

-- R5: Students can see their own enrollments
-- R5: Instructors can see enrollments in their courses
create policy "enrollments_select_self_or_instructor" on public.enrollments
for select
using (
  -- Student sees own enrollment
  (auth.role() = 'authenticated' and student_id = auth.uid())
  -- Instructor sees enrollments for their courses
  or (auth.role() = 'authenticated' and public.is_course_instructor(course_id))
);

-- R6: Anonymous visitors cannot change anything (Handled by default deny + explicit authenticated checks above)
-- R7: Service role bypasses RLS automatically by Supabase design
```

