```sql
-- Enable RLS on all tables
alter table public.patients enable row level security;
alter table public.care_team enable row level security;
alter table public.records enable row level security;

-- Helper function to check if the current user is a doctor in the care team for a specific patient
create or replace function public.is_care_team_doctor(target_patient_id bigint)
returns boolean as $$
  select exists (
    select 1
    from public.care_team ct
    where ct.patient_id = target_patient_id
      and ct.doctor_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check MFA level (aal2)
create or replace function public.has_mfa_level_2()
returns boolean as $$
  select (auth.jwt() ->> 'aal') = 'aal2';
$$ language sql security definer;

-- ==========================================
-- PATIENTS TABLE POLICIES
-- ==========================================

-- R1: Patients can read their own patient row
create policy "patients_read_own"
on public.patients
for select
using (
  auth.uid() = user_id
);

-- R2: Doctors can read patient rows if they are in the care team AND have aal2
create policy "patients_read_by_care_team_doctor"
on public.patients
for select
using (
  public.has_mfa_level_2()
  and public.is_care_team_doctor(id)
);

-- R5: Users can see care-team rows involving them (handled in care_team policies, but patients need to join)
-- No additional patient policy needed for care_team visibility here, handled below.

-- No insert/update/delete for patients via app (implicit deny for these actions unless specified)
-- R7: Anonymous cannot see anything (RLS is enabled, no policy for anon means deny)

-- ==========================================
-- CARE_TEAM TABLE POLICIES
-- ==========================================

-- R5: Users can see care-team rows where they are the patient or the doctor
create policy "care_team_read_involved_users"
on public.care_team
for select
using (
  auth.uid() = doctor_id 
  OR 
  exists (
    select 1 from public.patients p 
    where p.id = care_team.patient_id 
    and p.user_id = auth.uid()
  )
);

-- R5: Nobody can change care teams through the app
-- Explicitly deny insert, update, delete by not creating policies for these actions for authenticated users.
-- Service role bypasses RLS (R8).

-- ==========================================
-- RECORDS TABLE POLICIES
-- ==========================================

-- R1: Patients can read their own records
create policy "records_read_own"
on public.records
for select
using (
  exists (
    select 1 from public.patients p
    where p.id = records.patient_id
    and p.user_id = auth.uid()
  )
);

-- R2: Doctors can read records of patients in their care team ONLY with aal2
create policy "records_read_by_care_team_doctor"
on public.records
for select
using (
  public.has_mfa_level_2()
  and public.is_care_team_doctor(patient_id)
);

-- R3: Doctors can add records for patients in their care team ONLY with aal2
create policy "records_insert_by_care_team_doctor"
on public.records
for insert
with check (
  public.has_mfa_level_2()
  and public.is_care_team_doctor(patient_id)
  and auth.uid() = author_id
);

-- R3: Patients cannot add records (No policy for insert for patients)
-- R4: Records can never be changed or deleted (No update/delete policies created)

-- ==========================================
-- GRANTS
-- ==========================================

-- Revoke all from anon explicitly to be safe (though RLS handles row access, table access needs grant)
revoke all on table public.patients from anon;
revoke all on table public.care_team from anon;
revoke all on table public.records from anon;

-- Grant usage to authenticated users (RLS will filter rows)
grant usage on schema public to authenticated;
grant select on table public.patients to authenticated;
grant select on table public.care_team to authenticated;
grant select, insert on table public.records to authenticated;

-- Ensure service_role has full access (usually default, but explicit for clarity if needed in context)
-- In Supabase, service_role bypasses RLS automatically, so no specific policy needed.
