  to authenticated
  using (false);

create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_from_user uuid;
  v_from_balance integer;
  v_to_balance integer;
  v_new_transfer_id bigint;
begin
  v_from_user := auth.uid();

  if v_from_user is null then
    raise exception 'Caller not signed in';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  if p_to = v_from_user then
    raise exception 'Recipient cannot be the caller';
  end if;

  select balance into v_from_balance
  from public.wallets
  where user_id = v_from_user
  for update;

  if v_from_balance is null then
    raise exception 'Caller has no wallet';
  end if;

  if v_from_balance < p_amount then
    raise exception 'Insufficient balance';
  end if;

  select balance into v_to_balance
  from public.wallets
  where user_id = p_to
  for update;

  if v_to_balance is null then
    raise exception 'Recipient has no wallet';
  end if;

  update public.wallets
  set balance = balance - p_amount
  where user_id = v_from_user;

  update public.wallets
  set balance = balance + p_amount
  where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount)
  values (v_from_user, p_to, p_amount)
  returning id into v_new_transfer_id;

  return v_new_transfer_id;
end;
$$;

grant usage on schema public to anon, authenticated;
grant execute on function public.send_points(uuid, integer) to authenticated;
grant select on public.wallets to authenticated;
grant select on public.transfers to authenticated;
