```sql
alter table public.books enable row level security;
alter table public.loans enable row level security;
alter table public.librarians enable row level security;

-- Helper function to check if current user is a librarian
create or replace function public.is_librarian()
returns boolean as $$
  select exists (
    select 1 from public.librarians
    where user_id = auth.uid()
  );
$$ language sql security definer stable;

-- Helper function to count active loans for a user
create or replace function public.count_active_loans(target_user_id uuid)
returns integer as $$
  select count(*)::int
  from public.loans
  where borrower_id = target_user_id
    and returned_on is null;
$$ language sql security definer stable;

-- Helper function to count active loans for a book
create or replace function public.count_active_loans_for_book(target_book_id bigint)
returns integer as $$
  select count(*)::int
  from public.loans
  where book_id = target_book_id
    and returned_on is null;
$$ language sql security definer stable;

-- R1: Signed-in users can see the whole book catalogue. Anonymous visitors cannot.
create policy "authenticated_users_view_books"
on public.books
for select
to authenticated
using (true);

-- R5: Only librarians can add books or change the catalogue.
create policy "librarians_insert_books"
on public.books
for insert
to authenticated
with check (public.is_librarian());

create policy "librarians_update_books"
on public.books
for update
to authenticated
using (public.is_librarian())
with check (public.is_librarian());

-- R7: Anonymous visitors cannot see or change anything (explicit deny via lack of policy, but adding explicit select deny for clarity if needed, though default is no access)
-- No policies for anon on books, loans, librarians ensures R7.

-- R2: Members can see their own loans; librarians can see every loan.
create policy "users_view_own_loans"
on public.loans
for select
to authenticated
using (
  borrower_id = auth.uid() OR public.is_librarian()
);

-- R3: Members can borrow a book (insert loan) with constraints.
-- Constraints: 
-- 1. Must be themselves (borrower_id = auth.uid())
-- 2. Book must have free copies (active loans < copies)
-- 3. User must have < 3 active loans
create policy "users_insert_loans"
on public.loans
for insert
to authenticated
with check (
  borrower_id = auth.uid()
  AND (
    select copies from public.books where id = book_id
  ) > (
    select public.count_active_loans_for_book(book_id)
  )
  AND (
    select public.count_active_loans(auth.uid())
  ) < 3
);

-- R4: Members can return their own active loans by setting returned_on.
-- Nothing else can be changed. Returned loans cannot be changed.
create policy "users_update_own_loans_return"
on public.loans
for update
to authenticated
using (
  -- Can only update if it's their loan AND it's currently active (returned_on is null)
  borrower_id = auth.uid()
  AND returned_on is null
)
with check (
  -- Ensure borrower_id and book_id and borrowed_on haven't changed, only returned_on is set
  borrower_id = auth.uid()
  AND book_id = (select book_id from public.loans where id = id) -- Prevent changing book
  AND borrowed_on = (select borrowed_on from public.loans where id = id) -- Prevent changing date
  AND returned_on is not null -- Must set returned_on
);

-- R5: Nobody can delete loans.
-- No delete policy created for anyone except service_role (which bypasses RLS).

-- R6: Users can see whether they themselves are a librarian. Nobody can change librarians through the app.
create policy "users_view_own_librarian_status"
on public.librarians
for select
to authenticated
using (user_id = auth.uid());

-- No insert/update/delete policies for librarians table for authenticated users, satisfying "Nobody can change librarians through the app".

-- Grants for authenticated users to interact with tables (policies handle row-level, grants handle table-level)
grant usage on schema public to authenticated;
grant select on public.books to authenticated;
grant insert, update on public.books to authenticated; -- Controlled by policies
grant select on public.loans to authenticated;
grant insert, update on public.loans to authenticated; -- Controlled by policies
grant select on public.librarians to authenticated;

-- Revoke direct access from anon to ensure R7
revoke all on public.books from anon;
revoke all on public.loans from anon;
revoke all on public.librarians from anon;
revoke usage on schema public from anon;
```

