create function public.is_friends(user_a uuid, user_b uuid)
returns boolean as $$
  select exists (
    select 1 from public.friendships f
    where 
      ((f.requester_id = user_a and f.addressee_id = user_b) or
       (f.requester_id = user_b and f.addressee_id = user_a))
      and f.status = 'accepted'
  );
$$ language sql security definer stable;

create policy "anon can read public posts"
on public.posts
for select
to anon
using (audience = 'public');

create policy "authenticated can read allowed posts"
on public.posts
for select
to authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or (audience = 'friends' and public.is_friends(auth.uid(), author_id))
);

create policy "users can insert own posts"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "users can update own posts"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "users can delete own posts"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "users can view friendships they are part of"
on public.friendships
for select
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "users can send friend requests"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
  and requester_id <> addressee_id
);

create policy "addressee can accept pending requests"
on public.friendships
for update
to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
  and requester_id = requester_id
  and addressee_id = addressee_id
);

create policy "users can delete friendships they are part of"
on public.friendships
for delete
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

grant usage on schema public to anon, authenticated;
grant select on public.posts to anon, authenticated;
grant select, insert, update, delete on public.posts to authenticated;
grant select on public.friendships to authenticated;
grant insert, update, delete on public.friendships to authenticated;
grant execute on function public.is_friends to authenticated;
```

