alter table public.guestbook_entries enable row level security;

-- Helper function to check if user is site owner (service_role or specific claim)
create or replace function public.is_site_owner()
returns boolean as $$
begin
  -- service_role bypasses RLS automatically, but for explicit checks in policies:
  if auth.role() = 'service_role' then
    return true;
  end;
  -- Check for a custom claim 'site_owner' in JWT, optional fallback
  return (auth.jwt() ->> 'site_owner')::boolean = true;
end;
$$ language plpgsql security definer;

-- R1: Anyone can read approved entries
create policy "select_approved_entries"
on public.guestbook_entries
for select
using (
  is_approved = true
);

-- R3: Signed-in users can read their own entries (approved or not)
create policy "select_own_entries"
on public.guestbook_entries
for select
to authenticated
using (
  author_id = auth.uid()
);

-- R2: Anyone can insert new entries
-- Enforce: is_approved=false, author_id matches auth.uid() (or null for anon)
create policy "insert_entries"
on public.guestbook_entries
for insert
with check (
  is_approved = false
  and (
    (auth.role() = 'anon' and author_id is null)
    or (auth.role() = 'authenticated' and author_id = auth.uid())
  )
);

-- R3: Signed-in users can delete their own entries
create policy "delete_own_entries"
on public.guestbook_entries
for delete
to authenticated
using (
  author_id = auth.uid()
);

-- R3/R5: Site owner (service_role logic handled by bypass, but explicit policy for clarity if needed via claim)
-- Note: service_role bypasses RLS entirely, so no specific policy needed for them to delete unauthored rows.
-- However, if a human admin uses 'authenticated' role with a claim, this covers it:
create policy "delete_all_entries_for_owner"
on public.guestbook_entries
for delete
using (
  public.is_site_owner()
);

-- R4: Nobody can update entries (explicit deny by omission of UPDATE policy)
-- No UPDATE policy created ensures updates are blocked for all non-bypass roles.

-- Grants for public usage
grant usage on schema public to anon, authenticated;
grant select, insert, delete on public.guestbook_entries to anon, authenticated;
-- Revoke update explicitly to be safe despite missing policy
revoke update on public.guestbook_entries from anon, authenticated;
