alter table public.contracts enable row level security;
alter table public.contract_shares enable row level security;
alter table public.contract_versions enable row level security;
alter table public.contract_tags enable row level security;

create function public.is_contract_owner_or_shared(p_contract_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.contracts c
    where c.id = p_contract_id and c.owner_id = auth.uid()
  )
  or exists (
    select 1 from public.contract_shares cs
    where cs.contract_id = p_contract_id and cs.user_id = auth.uid()
  );
$$ language sql security definer stable;

create function public.is_contract_owner(p_contract_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.contracts c
    where c.id = p_contract_id and c.owner_id = auth.uid()
  );
$$ language sql security definer stable;

-- Contracts Policies
create policy "owners_full_access" on public.contracts
  for all
  to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy "shared_read_only" on public.contracts
  for select
  to authenticated
  using (public.is_contract_owner_or_shared(id));

-- Contract Versions Policies
create policy "versions_read_shared" on public.contract_versions
  for select
  to authenticated
  using (public.is_contract_owner_or_shared(contract_id));

create policy "versions_insert_shared" on public.contract_versions
  for insert
  to authenticated
  with check (
    public.is_contract_owner_or_shared(contract_id)
    and created_by = auth.uid()
  );

-- Contract Tags Policies
create policy "tags_read_shared" on public.contract_tags
