-- Enable RLS on all tables
alter table public.projects enable row level security;
alter table public.assignments enable row level security;
alter table public.periods enable row level security;
alter table public.time_entries enable row level security;

-- Helper function to check if a user is assigned to a project
create or replace function public.is_assigned_to_project(check_project_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select exists (
    select 1 from public.assignments a
    where a.project_id = check_project_id
      and a.user_id = auth.uid()
  );
$$;

-- Helper function to check if a period is locked
create or replace function public.is_period_locked(check_period_id bigint)
returns boolean
language sql
security definer
stable
as $$
  select coalesce(
    (select p.is_locked from public.periods p where p.id = check_period_id),
    false
  );
$$;

-- R1: Users can see their own time entries
create policy "Users can view own time entries"
on public.time_entries
for select
to authenticated
using (user_id = auth.uid());

-- R1: Users can see projects they are assigned to
create policy "Users can view assigned projects"
on public.projects
for select
to authenticated
using (public.is_assigned_to_project(id));

-- R1: Users can see their own assignments
create policy "Users can view own assignments"
on public.assignments
for select
to authenticated
using (user_id = auth.uid());

-- R1: Users can see every pay period
create policy "Users can view all periods"
on public.periods
for select
to authenticated
using (true);

-- R2 & R3: Users can insert their own entries for assigned projects, not in locked periods
create policy "Users can insert own time entries"
on public.time_entries
for insert
to authenticated
with check (
  user_id = auth.uid()
  and public.is_assigned_to_project(project_id)
  and not public.is_period_locked(period_id)
);

-- R2 & R3: Users can update their own entries for assigned projects, not in locked periods
-- Prevents moving into/out of locked periods by checking both old and new period_id
create policy "Users can update own time entries"
on public.time_entries
for update
to authenticated
using (
  user_id = auth.uid()
  and public.is_assigned_to_project(project_id)
  and not public.is_period_locked(period_id)
)
with check (
  user_id = auth.uid()
  and public.is_assigned_to_project(project_id)
  and not public.is_period_locked(period_id)
);

-- R2 & R3: Users can delete their own entries, only if the period is not locked
create policy "Users can delete own time entries"
on public.time_entries
