-- Enable RLS
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.invites enable row level security;

-- Helper function to check if user is admin of an org
create or replace function public.is_org_admin(target_org_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.org_members
    where org_id = target_org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$ language sql security definer stable;

-- Helper function to get user's verified email from JWT
create or replace function public.get_verified_email()
returns text as $$
  select auth.jwt() ->> 'email';
$$ language sql security definer stable;

-- R1: Members can see their organizations
create policy "orgs_view_members" on public.orgs
  for select
  to authenticated
  using (
    exists (
      select 1 from public.org_members
      where org_id = public.orgs.id
        and user_id = auth.uid()
    )
  );

-- R1: Members can see every member of their organizations
create policy "org_members_view_members" on public.org_members
  for select
  to authenticated
  using (
    exists (
      select 1 from public.org_members AS om
      where om.org_id = public.org_members.org_id
        and om.user_id = auth.uid()
    )
  );

-- R2: Only admins can see invites for their org
create policy "invites_view_admins" on public.invites
  for select
  to authenticated
  using (
    public.is_org_admin(org_id)
  );

-- R2: Only admins can create invites for their org
create policy "invites_insert_admins" on public.invites
  for insert
  to authenticated
  with check (
    public.is_org_admin(org_id)
    and invited_by = auth.uid()
    and accepted_at is null
    and expires_at > now()
  );

-- R2: Only admins can delete invites for their org
create policy "invites_delete_admins" on public.invites
  for delete
  to authenticated
  using (
    public.is_org_admin(org_id)
  );

-- R4: Prevent direct inserts/updates/deletes to orgs and org_members (except via RPC)
-- Deny all direct modifications to orgs
create policy "orgs_no_modifications" on public.orgs
  for all
  to authenticated
  using (false)
  with check (false);

-- Deny all direct modifications to org_members
create policy "org_members_no_modifications" on public.org_members
  for all
  to authenticated
  using (false)
  with check (false);

-- R5: Anonymous users cannot see or change anything (default deny, but explicit for clarity)
create policy "orgs_anon_deny" on public.orgs for all to anon using (false) with check (false);
create policy "org_members_anon_deny" on public.org_members for all to anon using (false) with check (false);
create policy "invites_anon_deny" on public.invites for all to anon using (false) with check (false);

-- R3: accept_invite function
create or replace function public.accept_invite(p_token text)
returns bigint as $$
declare
  v_invite_record public.invites%rowtype;
  v_user_email text;
  v_org_id bigint;
  v_role text;
begin
  -- Check if user is signed in
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  -- Get verified email from JWT
  v_user_email := public.get_verified_email();
  if v_user_email is null then
    raise exception 'Verified email not found in JWT';
  end if;

  -- Fetch invite record
  select * into v_invite_record
  from public.invites
  where token = p_token;

  -- Check if token exists
  if not found then
    raise exception 'Invalid invite token';
  end if;

  -- Check if invite already accepted
  if v_invite_record.accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  -- Check if invite expired
  if v_invite_record.expires_at <= now() then
    raise exception 'Invite has expired';
  end if;

  -- Check email match (case-insensitive)
  if lower(v_invite_record.email) != lower(v_user_email) then
    raise exception 'Invite email does not match user verified email';
  end if;

  -- Add user to org_members
  insert into public.org_members (org_id, user_id, role)
  values (v_invite_record.org_id, auth.uid(), v_invite_record.role)
  on conflict (org_id, user_id) do nothing;

  -- Mark invite as accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_invite_record.org_id;
end;
$$ language plpgsql security definer;

-- Grant execute on accept_invite to authenticated users
grant execute on function public.accept_invite(text) to authenticated;
revoke execute on function public.accept_invite(text) from anon;

-- Ensure service_role bypasses RLS (default behavior, but explicit grants for clarity)
-- Service role automatically bypasses RLS in Supabase, no additional policies needed
