-- Create the accept_invite function
create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
  declare
    v_org_id bigint;
    v_role text;
    v_email text;
    v_invite_email text;
  begin
    -- Check if user is signed in
    if auth.uid() is null then
      raise exception 'not_authenticated';
    end if;

    -- Get invite details
    select i.org_id, i.role, i.email, i.expires_at, i.accepted_at
    into v_org_id, v_role, v_invite_email, expires_at, accepted_at
    from public.invites i
    where i.token = p_token;

    -- Check if token exists
    if v_org_id is null then
      raise exception 'invalid_token';
    end if;

    -- Check if already accepted (using variables from select above requires proper declaration or re-select)
    -- Re-declare or use found%rowtype. Let's refactor slightly for clarity within the block.
    declare
      rec record;
    begin
      select * into rec from public.invites where token = p_token;

      if rec.id is null then -- token not found (using id check as proxy for not found since token is PK)
         -- Actually token is PK, so if rec.token is null
         if rec.token is null then
            raise exception 'invalid_token';
         end if;
      end if;

      if rec.accepted_at is not null then
        raise exception 'invite_already_accepted';
      end if;

      if rec.expires_at <= now() then
        raise exception 'invite_expired';
      end if;

      -- Get caller's verified email
      v_email := public.get_verified_email();

      if v_email is null then
        raise exception 'no_verified_email';
      end if;

      -- Compare emails case-insensitive
      if lower(v_email) <> lower(rec.email) then
        raise exception 'email_mismatch';
      end if;

      -- Add user to org_members
      insert into public.org_members (org_id, user_id, role)
      values (rec.org_id, auth.uid(), rec.role)
      on conflict (org_id, user_id) do nothing; -- Should not happen based on logic, but safe

      -- Mark invite as accepted
      update public.invites
      set accepted_at = now()
      where token = p_token;

      return rec.org_id;
    end;
  end;
$$;

-- Grant execute on accept_invite to authenticated users
grant execute on function public.accept_invite(text) to authenticated;

