create policy "allow_service_role_full_access"
on public.categories
for all
to service_role
using (true)
with check (true);

create policy "allow_authenticated_read_builtin_and_own"
on public.categories
for select
to authenticated
using (
  user_id is null
  or user_id = auth.uid()
);

create policy "allow_authenticated_insert_own_only"
on public.categories
for insert
to authenticated
with check (
  user_id = auth.uid()
);

create policy "allow_authenticated_update_own_only"
on public.categories
for update
to authenticated
using (
  user_id = auth.uid()
)
with check (
  user_id = auth.uid()
);

create policy "allow_authenticated_delete_own_only"
on public.categories
for delete
to authenticated
using (
  user_id = auth.uid()
);

create function public.prevent_builtin_category_modification()
returns trigger as $$
begin
  if tg_op = 'INSERT' then
    if new.user_id is null then
      raise exception 'Cannot create built-in categories via app';
    end if;
  elsif tg_op = 'UPDATE' then
    if old.user_id is null then
      raise exception 'Cannot modify built-in categories';
    end if;
    if new.user_id is null then
      raise exception 'Cannot convert user category to built-in';
    end if;
    if new.user_id <> old.user_id then
      raise exception 'Cannot change ownership of categories';
    end if;
  elsif tg_op = 'DELETE' then
    if old.user_id is null then
      raise exception 'Cannot delete built-in categories';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trig_prevent_builtin_category_modification
before insert or update or delete on public.categories
for each row
execute function public.prevent_builtin_category_modification();

revoke all on public.categories from anon;
revoke all on public.categories from authenticated;
grant select on public.categories to authenticated;
grant insert on public.categories to authenticated;
grant update on public.categories to authenticated;
grant delete on public.categories to authenticated;
