-- Enable RLS on storage.objects
alter table storage.objects enable row level security;

-- Helper function to extract user id from JWT and validate avatar filename format
create or replace function storage.matches_user_avatar_pattern()
returns boolean as $$
declare
  _uid uuid;
  _bucket text;
  _name text;
  _ext text;
begin
  -- Get current user UID
  _uid := auth.uid();
  if _uid is null then
    return false;
  end;

  -- Get bucket and name from the row context (assumed to be called within a policy check)
  -- We rely on the policy passing the correct context or we access NEW/OLD via TG_OP if triggered,
  -- but for RLS policies we access the row directly. 
  -- However, functions used in policies can't directly see NEW/OLD unless passed.
  -- Instead, we will write the logic directly in the policy or use a function that accepts parameters.
  -- Let's refactor to a function that takes bucket and name.
  return true; -- Placeholder, logic moved to specific policies for clarity and performance
end;
$$ language plpgsql security definer;

-- Drop helper if it exists to recreate with correct signature
drop function if exists storage.is_owner_avatar(text, text);

-- Helper function: checks if the user owns the specific avatar file
create function storage.is_owner_avatar(_bucket text, _name text)
returns boolean as $$
declare
  _uid uuid;
  _expected_name text;
begin
  _uid := auth.uid();
  if _uid is null then
    return false;
  end;

  -- Check bucket
  if _bucket <> 'avatars' then
    return false;
  end;

  -- Check filename format: <uid>.png or <uid>.jpg
  -- The name must be exactly the uid + extension, no folders (no '/')
  if position('/' in _name) > 0 then
    return false;
  end;

  if _name = _uid::text || '.png' or _name = _uid::text || '.jpg' then
    return true;
  end;

  return false;
end;
$$ language plpgsql security definer;

-- Policy R1: Anyone (including anon) can read objects in 'avatars'
create policy "Public read access to avatars"
on storage.objects
for select
using (
  bucket_id = 'avatars'
);

-- Policy R2 & R4: Authenticated users can upload/replace/delete ONLY their own avatar in 'avatars'
-- Anonymous users cannot do this because auth.uid() is null, causing is_owner_avatar to return false.
create policy "Users manage own avatar"
on storage.objects
for all
to authenticated
using (
  storage.is_owner_avatar(bucket_id, name)
)
with check (
  storage.is_owner_avatar(bucket_id, name)
);

-- Policy R3 & R4: Explicitly deny everything else for anon and authenticated users
-- By default, if no policy matches, access is denied. 
-- However, we need to ensure 'docs' and other buckets are strictly inaccessible.
-- The policies above are restrictive enough:
-- - Select only allows 'avatars'.
-- - All (insert/update/delete) only allows 'avatars' AND matching user ID.
-- Therefore, 'docs' and other buckets are implicitly denied for select and all.
-- No explicit DENY policy is needed in Postgres RLS (default is deny).

-- Ensure service_role bypasses RLS (default behavior, but explicit grant for clarity if needed)
-- Service role bypasses RLS by default in Supabase, so no specific policy needed for R5.

-- Revoke public access to buckets metadata if not desired (optional, but R3 says objects in other buckets cannot be read)
-- The object policies handle the data. Bucket listing is controlled by separate bucket policies usually, 
-- but the prompt focuses on storage.objects rules. 
-- Assuming standard Supabase setup where bucket-level read is separate. 
-- Based on strict interpretation of R3 on objects:
-- The `using` clause in SELECT policy `bucket_id = 'avatars'` ensures objects in 'docs' cannot be selected.

-- Grant necessary permissions to roles for the table structure (standard Supabase setup usually has these)
-- Ensuring anon and authenticated have usage on the schema
grant usage on schema storage to anon, authenticated;
grant select on storage.objects to anon, authenticated;
grant insert, update, delete on storage.objects to authenticated;
-- Anon should not have write permissions
revoke insert, update, delete on storage.objects from anon;
