  -- we will write the policies with inline checks for clarity and correctness.
  return true; -- Placeholder, actual logic is in policies
end;
$$ language plpgsql security definer;

-- R1: Anyone (anon/authenticated) can READ objects in 'avatars' bucket
create policy "avatar_read_public"
on storage.objects
for select
using (
  bucket_id = 'avatars'
);

-- R2 & R4: Authenticated users can INSERT/UPDATE/DELETE only their own avatar in 'avatars'
-- Pattern: <user_id>.png or <user_id>.jpg, no folders (name must not contain '/')
create policy "avatar_write_owner"
on storage.objects
for all
to authenticated
with check (
  bucket_id = 'avatars'
  and owner = auth.uid()
  and (name = auth.uid()::text || '.png' or name = auth.uid()::text || '.jpg')
  and position('/' in name) = 0
)
using (
  bucket_id = 'avatars'
  and owner = auth.uid()
  and (name = auth.uid()::text || '.png' or name = auth.uid()::text || '.jpg')
  and position('/' in name) = 0
);

-- R3: Explicitly deny access to any bucket other than 'avatars' for non-service roles
-- This is implicitly handled by the above policies only allowing 'avatars', 
-- but to be explicit and safe against future policies, we ensure no other bucket is accessible.
-- Since default is deny if no policy matches, and we only added policies for 'avatars',
-- other buckets are already denied for select/insert/update/delete for anon/authenticated.
-- No extra policy needed for denial, as RLS defaults to deny.

-- R5: Service role bypasses RLS automatically in Supabase, no policy needed.

