-- Enable RLS on storage.objects
alter table storage.objects enable row level security;

-- Helper function to extract user id from object name for avatar bucket
create or replace function storage.get_avatar_owner_id(path text)
returns uuid as $$
declare
  file_name text;
  user_id_text text;
begin
  -- Extract filename from path (assuming top-level only for avatars)
  file_name := reverse(split_part(reverse(path), '/', 1));

  -- Remove extension (.png or .jpg)
  if file_name like '%.png' then
    user_id_text := left(file_name, length(file_name) - 4);
  elsif file_name like '%.jpg' then
    user_id_text := left(file_name, length(file_name) - 4);
  else
    return null;
  end if;

  -- Validate and return as uuid
  begin
    return user_id_text::uuid;
  exception when others then
    return null;
  end;
end;
$$ language plpgsql security definer;

-- Policy R1: Anyone can read objects in 'avatars' bucket
create policy "avatars_public_read"
on storage.objects
for select
using (
  bucket_id = 'avatars'
);

-- Policy R2: Authenticated users can upload/update/delete their own avatar
-- Conditions: bucket is 'avatars', filename matches <user_id>.png or <user_id>.jpg, owner matches user
create policy "avatars_user_write"
on storage.objects
for all
to authenticated
using (
  bucket_id = 'avatars'
  and owner = auth.uid()
  and (
    (name = auth.uid()::text || '.png')
    or
    (name = auth.uid()::text || '.jpg')
  )
)
with check (
  bucket_id = 'avatars'
  and owner = auth.uid()
  and (
    (name = auth.uid()::text || '.png')
    or
    (name = auth.uid()::text || '.jpg')
  )
);

-- Policy R3 & R4: Explicitly deny all other access for non-service roles
-- By default, if no policy matches, access is denied. 
-- We ensure no policies exist for 'docs' or other buckets for anon/authenticated.
-- The absence of policies for 'docs' for select/insert/update/delete enforces R3.
-- The absence of insert/update/delete policies for 'avatars' for anon enforces R4.

-- Revoke any potentially inherited permissions on storage.objects from public/anon for write operations
revoke insert, update, delete on storage.objects from anon;
revoke insert, update, delete on storage.objects from authenticated;

-- Ensure service_role bypasses RLS (handled automatically by Supabase, but explicit grant for clarity on select if needed)
-- Service role bypasses RLS by definition in Supabase, so no specific policy needed for R5.
