```sql
alter table public.rides enable row level security;
alter table public.ride_bookings enable row level security;

create function public.is_driver_of_ride(ride_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.rides r
    where r.id = ride_id and r.driver_id = auth.uid()
  );
$$ language sql security definer stable;

create function public.ride_has_departed(ride_id bigint)
returns boolean as $$
  select r.departs_at <= now()
  from public.rides r
  where r.id = ride_id;
$$ language sql security definer stable;

create function public.confirmed_bookings_count(ride_id bigint)
returns integer as $$
  select count(*)::int
  from public.ride_bookings rb
  where rb.ride_id = ride_id and rb.status = 'confirmed';
$$ language sql security definer stable;

-- R1: Rides Policies
-- Signed-in users can see every ride
create policy "rides_select_authenticated" on public.rides
  for select
  to authenticated
  using (true);

-- Drivers can create rides as themselves
create policy "rides_insert_driver" on public.rides
  for insert
  to authenticated
  with check (driver_id = auth.uid());

-- Drivers can edit their own rides
create policy "rides_update_driver" on public.rides
  for update
  to authenticated
  using (driver_id = auth.uid())
  with check (driver_id = auth.uid());

-- Drivers can delete their own rides
create policy "rides_delete_driver" on public.rides
  for delete
  to authenticated
  using (driver_id = auth.uid());

-- R2, R3, R4: Ride Bookings Policies
-- Passengers can see their own bookings; drivers can see every booking on their rides
create policy "bookings_select_passenger_or_driver" on public.ride_bookings
  for select
  to authenticated
  using (
    passenger_id = auth.uid()
    OR
    public.is_driver_of_ride(ride_id)
  );

-- R3: Signed-in users can request a seat as themselves on rides that have not departed and they are not driving
create policy "bookings_insert_request" on public.ride_bookings
  for insert
  to authenticated
  with check (
    passenger_id = auth.uid()
    AND
    status = 'requested'
    AND
    NOT public.ride_has_departed(ride_id)
    AND
    NOT public.is_driver_of_ride(ride_id)
  );

-- R3: Passengers can withdraw their own bookings before departure
create policy "bookings_delete_passenger" on public.ride_bookings
  for delete
  to authenticated
  using (
    passenger_id = auth.uid()
    AND
    NOT public.ride_has_departed(ride_id)
  );

-- R4: Only the driver can confirm or decline requests on their ride, only before departure
-- Constraint: Confirm only if seats available
create policy "bookings_update_driver_status" on public.ride_bookings
  for update
  to authenticated
  using (
    public.is_driver_of_ride(ride_id)
    AND
    NOT public.ride_has_departed(ride_id)
    AND
    status = 'requested'
  )
  with check (
    public.is_driver_of_ride(ride_id)
    AND
    NOT public.ride_has_departed(ride_id)
    AND
    status in ('confirmed', 'declined')
    AND
    (
      status = 'declined'
      OR
      (status = 'confirmed' AND public.confirmed_bookings_count(ride_id) < (select seats from public.rides where id = ride_id))
    )
  );

-- Revoke all from anon to satisfy R5
revoke all on table public.rides from anon;
revoke all on table public.ride_bookings from anon;
revoke all on table public.rides from authenticated;
revoke all on table public.ride_bookings from authenticated;

-- Grant specific permissions required for the policies to function for authenticated users
grant select on table public.rides to authenticated;
grant insert on table public.rides to authenticated;
grant update on table public.rides to authenticated;
grant delete on table public.rides to authenticated;

grant select on table public.ride_bookings to authenticated;
grant insert on table public.ride_bookings to authenticated;
grant update on table public.ride_bookings to authenticated;
grant delete on table public.ride_bookings to authenticated;

-- Grant execute on helper functions to authenticated
grant execute on function public.is_driver_of_ride to authenticated;
grant execute on function public.ride_has_departed to authenticated;
grant execute on function public.confirmed_bookings_count to authenticated;
