    and r.departs_at > now()
  )
);

create function public.check_booking_update_rules()
returns trigger as $$
declare
  v_driver_id uuid;
  v_departs_at timestamptz;
  v_seats integer;
  v_confirmed_count integer;
begin
  if tg_op = 'UPDATE' then
    if new.status = old.status then
      raise exception 'Nothing else about a booking can change';
    end if;

    if new.status not in ('confirmed', 'declined') then
      raise exception 'Only status can be updated to confirmed or declined';
    end if;

    select r.driver_id, r.departs_at, r.seats
    into v_driver_id, v_departs_at, v_seats
    from public.rides r
    where r.id = new.ride_id;

    if v_driver_id is null then
      raise exception 'Ride not found';
    end if;

    if auth.uid() <> v_driver_id then
      raise exception 'Only the driver can confirm or decline requests';
    end if;

    if v_departs_at <= now() then
      raise exception 'Cannot update booking after departure';
    end if;

    if new.status = 'confirmed' then
      select count(*)
      into v_confirmed_count
      from public.ride_bookings rb
      where rb.ride_id = new.ride_id
      and rb.status = 'confirmed';

      if v_confirmed_count >= v_seats then
        raise exception 'Ride is full';
      end if;
    end if;

    return new;
  end if;
  return null;
end;
$$ language plpgsql security definer;

create trigger trg_check_booking_update_rules
before update on public.ride_bookings
for each row
execute function public.check_booking_update_rules();

