create function public.check_booking_update_limits()
returns trigger as $$
declare
  v_driver_id uuid;
  v_departs_at timestamptz;
  v_seats integer;
  v_confirmed_count integer;
begin
  if tg_op = 'UPDATE' then
    if old.status = new.status then
      return new;
