alter table public.approvers enable row level security;
alter table public.purchase_orders enable row level security;
alter table public.po_approvals enable row level security;

-- Helper function to check if a PO is decided
create or replace function public.is_po_decided(p_po_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.po_approvals where po_id = p_po_id
  );
$$ language sql security definer;

-- Helper function to get approver limit
create or replace function public.get_approver_limit(p_user_id uuid)
returns numeric as $$
  select limit_amount from public.approvers where user_id = p_user_id;
$$ language sql security definer;

-- R5: Approvers visibility (own row only)
create policy "approvers_select_own" on public.approvers
  for select
  to authenticated
  using (user_id = auth.uid());

-- R5: No updates or deletes on approvers via app
create policy "approvers_no_update" on public.approvers
  for update
  to authenticated
  using (false);

create policy "approvers_no_delete" on public.approvers
  for delete
  to authenticated
  using (false);

create policy "approvers_no_insert" on public.approvers
  for insert
  to authenticated
  with check (false);

-- R1 & R2: Purchase Orders Select (Requesters see own, Approvers see all)
create policy "purchase_orders_select" on public.purchase_orders
  for select
  to authenticated
  using (
    requester_id = auth.uid()
    OR
    exists (select 1 from public.approvers where user_id = auth.uid())
  );

-- R2: Purchase Orders Insert (Users create as themselves)
create policy "purchase_orders_insert" on public.purchase_orders
  for insert
  to authenticated
  with check (requester_id = auth.uid());

-- R2: Purchase Orders Update/Delete (Only own, only if not decided)
create policy "purchase_orders_update" on public.purchase_orders
  for update
  to authenticated
  using (
    requester_id = auth.uid()
    AND
    NOT public.is_po_decided(id)
  );

create policy "purchase_orders_delete" on public.purchase_orders
  for delete
  to authenticated
  using (
    requester_id = auth.uid()
    AND
    NOT public.is_po_decided(id)
  );

-- R4: PO Approvals Select (Requesters see decisions on their POs, Approvers see all)
create policy "po_approvals_select" on public.po_approvals
  for select
  to authenticated
  using (
    exists (select 1 from public.purchase_orders where id = po_id and requester_id = auth.uid())
    OR
    exists (select 1 from public.approvers where user_id = auth.uid())
  );

-- R3: PO Approvals Insert (Approvers only, within limit, not self-requested, PO not already decided)
create policy "po_approvals_insert" on public.po_approvals
  for insert
  to authenticated
  with check (
    -- Must be an approver
    exists (select 1 from public.approvers where user_id = auth.uid())
    AND
    -- Must be acting as themselves
    approver_id = auth.uid()
    AND
    -- Cannot approve own request
    NOT exists (
      select 1 from public.purchase_orders where id = po_id and requester_id = auth.uid()
    )
    AND
    -- Amount must be within limit
    (
      select amount from public.purchase_orders where id = po_id
    ) <= (
      select limit_amount from public.approvers where user_id = auth.uid()
    )
    AND
    -- PO must not already be decided
    NOT public.is_po_decided(po_id)
  );

-- R4: No updates or deletes on approvals
create policy "po_approvals_no_update" on public.po_approvals
  for update
  to authenticated
  using (false);

create policy "po_approvals_no_delete" on public.po_approvals
  for delete
  to authenticated
  using (false);

-- R6: Explicitly deny anon (though default is deny, being explicit for clarity)
create policy "deny_anon_all" on public.purchase_orders for all to anon using (false);
create policy "deny_anon_all_approvers" on public.approvers for all to anon using (false);
create policy "deny_anon_all_approvals" on public.po_approvals for all to anon using (false);

-- Grants for authenticated users to interact with tables
grant usage on schema public to authenticated;
grant select, insert, update, delete on public.purchase_orders to authenticated;
grant select, insert on public.po_approvals to authenticated;
grant select on public.approvers to authenticated;
grant usage on sequence public.purchase_orders_id_seq to authenticated;
```

