-- Enable RLS on all tables
alter table public.classes enable row level security;
alter table public.class_students enable row level security;
alter table public.guardians enable row level security;
alter table public.grades enable row level security;

-- Helper function to check if user is a teacher of a specific class
create or replace function public.is_teacher_of_class(class_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.classes c
    where c.id = class_id and c.teacher_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check if user is a student in a specific class
create or replace function public.is_student_in_class(class_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.class_students cs
    where cs.class_id = class_id and cs.student_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check if user is a guardian of a specific student
create or replace function public.is_guardian_of_student(student_id uuid)
returns boolean as $$
  select exists (
    select 1 from public.guardians g
    where g.student_id = student_id and g.guardian_id = auth.uid()
  );
$$ language sql security definer;

-- POLICIES FOR public.classes

-- R4: Signed-in users can see the class list.
create policy "classes_select_authenticated"
on public.classes
for select
to authenticated
using (true);

-- R4: Nobody can change classes.
create policy "classes_no_modifications"
on public.classes
for all
to authenticated
using (false)
with check (false);

-- POLICIES FOR public.class_students

-- R4: Students can see their own enrollments.
create policy "class_students_select_own"
on public.class_students
for select
to authenticated
using (student_id = auth.uid());

-- R4: Teachers can see rosters of their classes.
create policy "class_students_select_teacher_roster"
on public.class_students
for select
to authenticated
using (public.is_teacher_of_class(class_id));

-- R4: Nobody can change enrollments.
create policy "class_students_no_modifications"
on public.class_students
for all
to authenticated
using (false)
with check (false);

-- POLICIES FOR public.guardians

-- R4: Users can see guardian links that involve them (as guardian or student).
create policy "guardians_select_involved"
on public.guardians
for select
to authenticated
using (guardian_id = auth.uid() OR student_id = auth.uid());

-- R4: Nobody can change guardian links.
create policy "guardians_no_modifications"
on public.guardians
for all
to authenticated
using (false)
with check (false);

-- POLICIES FOR public.grades

-- R1: Students can read their own grades.
create policy "grades_select_student_own"
on public.grades
for select
to authenticated
using (student_id = auth.uid());

-- R1: Guardians can read grades of students they guard.
create policy "grades_select_guardian"
on public.grades
for select
to authenticated
using (public.is_guardian_of_student(student_id));

-- R1: Teachers can read every grade in classes they teach.
create policy "grades_select_teacher"
on public.grades
for select
to authenticated
using (public.is_teacher_of_class(class_id));

-- R2: Teachers can add grades in classes they teach, for enrolled students, with themselves as graded_by.
create policy "grades_insert_teacher"
on public.grades
for insert
to authenticated
with check (
  public.is_teacher_of_class(class_id)
  AND public.is_student_in_class(class_id)
  AND graded_by = auth.uid()
);

-- R2: Teachers can change grades in classes they teach, for enrolled students, with themselves as graded_by.
create policy "grades_update_teacher"
on public.grades
for update
to authenticated
using (
  public.is_teacher_of_class(class_id)
  AND public.is_student_in_class(class_id)
  AND graded_by = auth.uid()
)
with check (
  public.is_teacher_of_class(class_id)
  AND public.is_student_in_class(class_id)
  AND graded_by = auth.uid()
);

-- R2: Teachers can delete grades in classes they teach, for enrolled students, with themselves as graded_by.
create policy "grades_delete_teacher"
on public.grades
for delete
to authenticated
using (
  public.is_teacher_of_class(class_id)
  AND public.is_student_in_class(class_id)
  AND graded_by = auth.uid()
);

-- R3: Students and guardians cannot add, change or delete grades (Explicit deny via false check for non-teachers if they somehow match other criteria, 
-- but primarily enforced by the fact that R2 policies are the ONLY write policies and they require teacher status. 
-- However, to be explicit about R3 for clarity in logic: No additional policy needed as R2 covers all write access for authenticated users.
-- If a user is not a teacher, they fail the WITH CHECK/USING clauses of the write policies above.
-- We ensure no generic 'authenticated' write policy exists.

-- R5: Anonymous visitors cannot see or change anything.
-- By default, if no policy matches, access is denied. We explicitly ensure no policies exist for 'anon' role.
-- (No policies created for 'anon')

-- Grants for authenticated users to access tables (policies handle row-level filtering)
grant usage on schema public to authenticated;
grant select on public.classes to authenticated;
grant select on public.class_students to authenticated;
grant select on public.guardians to authenticated;
grant select, insert, update, delete on public.grades to authenticated;

-- Revoke direct access from anon
revoke all on public.classes from anon;
revoke all on public.class_students from anon;
revoke all on public.guardians from anon;
revoke all on public.grades from anon;
