```sql
-- Enable RLS
alter table public.folders enable row level security;
alter table public.folder_grants enable row level security;
alter table public.documents enable row level security;

-- Helper function to check if a user has access (read or edit) to a folder or any ancestor
create or replace function public.has_folder_access(
  target_folder_id bigint,
  required_can_edit boolean default false
)
returns boolean as $$
declare
  current_fid bigint;
  current_owner uuid;
  grant_can_edit boolean;
  is_owner boolean;
  has_grant boolean;
begin
  current_fid := target_folder_id;

  -- Traverse up the folder tree
  loop
    if current_fid is null then
      exit;
    end if;

    -- Get folder details
    select f.owner_id into current_owner
    from public.folders f
    where f.id = current_fid;

    if not found then
      return false;
    end if;

    -- Check ownership
    if current_owner = auth.uid() then
      if not required_can_edit then
        return true;
      end if;
      -- If edit required, ownership is sufficient
      return true;
    end if;

    -- Check grants
    select fg.can_edit into grant_can_edit
    from public.folder_grants fg
    where fg.folder_id = current_fid
      and fg.user_id = auth.uid();

    if found then
      if not required_can_edit then
        return true;
      elsif grant_can_edit then
        return true;
      end if;
    end if;

    -- Move to parent
    select parent_id into current_fid
    from public.folders
    where id = current_fid;
  end loop;

  return false;
end;
$$ language plpgsql security definer;

-- Helper function to check if user owns a folder or any ancestor (for write operations on folder structure)
create or replace function public.is_folder_owner_or_ancestor(
  target_folder_id bigint
)
returns boolean as $$
declare
  current_fid bigint;
  current_owner uuid;
begin
  current_fid := target_folder_id;

  loop
    if current_fid is null then
      exit;
    end if;

    select f.owner_id into current_owner
    from public.folders f
    where f.id = current_fid;

    if found and current_owner = auth.uid() then
      return true;
    end if;

    select parent_id into current_fid
    from public.folders
    where id = current_fid;
  end loop;

  return false;
end;
$$ language plpgsql security definer;

-- POLICIES: public.folders

-- R1 & R3 & R4: Select folders if owner, ancestor owner, or has grant on folder/ancestor
create policy "folders_select_access"
on public.folders
for select
to authenticated
using (
  public.has_folder_access(id, false)
);

-- R3: Insert top-level folders (parent_id is null) as own owner
-- R3: Insert subfolders only if user owns parent
create policy "folders_insert_access"
on public.folders
for insert
to authenticated
with check (
  owner_id = auth.uid()
  and (
    (parent_id is null)
    or (public.is_folder_owner_or_ancestor(parent_id))
  )
);

-- R3: Update folder (move folder? usually restricted, but name change allowed if owner)
-- Only owner of the folder itself can update its properties (name) or move it (change parent_id)
-- Moving requires ownership of new parent too, handled by check constraint logic implicitly via has_folder_access if we allowed moves, 
-- but rule says "Only owners... can create subfolders... and add/remove grants". 
-- Let's restrict UPDATE to owners of the folder itself to prevent unauthorized moves/renames.
create policy "folders_update_access"
on public.folders
for update
to authenticated
using (
  owner_id = auth.uid()
)
with check (
  owner_id = auth.uid() -- Cannot transfer ownership
  and (
    -- If changing parent, must own new parent
    (parent_id is not distinct from (select parent_id from public.folders where id = id)) -- No change
    or (public.is_folder_owner_or_ancestor(parent_id)) -- New parent owned by user
  )
);

-- R3: Delete folder only if owner
create policy "folders_delete_access"
on public.folders
for delete
to authenticated
using (
  owner_id = auth.uid()
);

-- POLICIES: public.documents

-- R1: Select documents if user has read access to the folder
create policy "documents_select_access"
on public.documents
for select
to authenticated
using (
  public.has_folder_access(folder_id, false)
);

-- R2: Insert documents if user has edit access to the folder
create policy "documents_insert_access"
on public.documents
for insert
to authenticated
with check (
  public.has_folder_access(folder_id, true)
);

-- R2: Update documents (including move) if user has edit access to the CURRENT folder (for edit) 
-- AND edit access to the NEW folder (if moving). 
-- Note: Standard RLS 'with check' validates the NEW row. 'using' validates the OLD row.
-- To move: Must have edit on old folder (to remove from there conceptually) and edit on new folder.
-- Simplified: Must have edit on the folder the document resides in (OLD) to modify it.
-- If folder_id changes, the WITH CHECK ensures they have edit rights on the NEW folder_id.
-- The USING ensures they had rights on the OLD folder_id to perform the update operation.
create policy "documents_update_access"
on public.documents
for update
to authenticated
using (
  public.has_folder_access(folder_id, true)
)
with check (
  public.has_folder_access(folder_id, true)
);

-- R2: Delete documents if user has edit access to the folder
create policy "documents_delete_access"
on public.documents
for delete
to authenticated
using (
  public.has_folder_access(folder_id, true)
);

-- POLICIES: public.folder_grants

-- R4: See grants given to me
create policy "folder_grants_select_self"
on public.folder_grants
for select
to authenticated
using (
  user_id = auth.uid()
);

-- R4: See grants on folders I own (directly or via ancestor)
create policy "folder_grants_select_owner"
on public.folder_grants
for select
to authenticated
using (
  public.is_folder_owner_or_ancestor(folder_id)
);

-- R3: Add/Remove grants only if owner of the folder (directly or via ancestor)
create policy "folder_grants_insert_access"
on public.folder_grants
for insert
to authenticated
with check (
  public.is_folder_owner_or_ancestor(folder_id)
);

create policy "folder_grants_delete_access"
