-- Enable RLS
alter table public.folders enable row level security;
alter table public.folder_grants enable row level security;
alter table public.documents enable row level security;

-- Helper function to check if a user has access (read or edit) to a folder or any ancestor
create or replace function public.has_folder_access(
  target_folder_id bigint,
  required_can_edit boolean default false
)
returns boolean as $$
declare
  current_fid bigint;
  current_owner uuid;
  grant_can_edit boolean;
begin
  current_fid := target_folder_id;

  -- Loop through the folder hierarchy
  loop
    if current_fid is null then
      exit;
    end if;

    -- Check ownership
    select owner_id into current_owner from public.folders where id = current_fid;
    if current_owner = auth.uid() then
      if not required_can_edit then
        return true;
      end if;
      -- If edit required, ownership is sufficient
      return true;
    end if;

    -- Check grants
    if required_can_edit then
      select can_edit into grant_can_edit from public.folder_grants 
      where folder_id = current_fid and user_id = auth.uid();
      if grant_can_edit = true then
        return true;
      end if;
    else
      -- Read access: any grant (edit implies read)
      select exists(
        select 1 from public.folder_grants 
        where folder_id = current_fid and user_id = auth.uid()
      ) into grant_can_edit;

      if grant_can_edit then
        return true;
      end if;
    end if;

    -- Move to parent
    select parent_id into current_fid from public.folders where id = current_fid;
  end loop;

  return false;
end;
$$ language plpgsql security definer;

-- Helper function to check if user can edit a folder (for document moves/updates)
create or replace function public.can_edit_folder(target_folder_id bigint)
returns boolean as $$
begin
  return public.has_folder_access(target_folder_id, true);
end;
$$ language plpgsql security definer;

-- Folders Policies

-- R1 & R3 & R4: Select folders if owned or granted (recursive)
create policy "folders_select_access" on public.folders
for select
to authenticated
using (public.has_folder_access(id, false));

-- R3: Insert top-level folders (parent_id is null) as owner
create policy "folders_insert_top_level" on public.folders
for insert
to authenticated
with check (parent_id is null and owner_id = auth.uid());

-- R3: Insert subfolders only if user can edit the parent
create policy "folders_insert_subfolder" on public.folders
for insert
to authenticated
with check (
  parent_id is not null 
  and public.can_edit_folder(parent_id) 
  and owner_id = auth.uid()
);

-- R3: Update folder (move folder or rename) - requires edit access to OLD location (to remove from tree context) and NEW parent if moving
-- Simplified: To update a folder (e.g. rename), you need edit access to it.
-- To move a folder (change parent_id), you need edit access to the folder itself AND the new parent.
create policy "folders_update_access" on public.folders
for update
to authenticated
using (public.can_edit_folder(id))
with check (
  public.can_edit_folder(id) 
  and (parent_id is null or public.can_edit_folder(parent_id))
);

-- R3: Delete folder - requires edit access
create policy "folders_delete_access" on public.folders
for delete
to authenticated
using (public.can_edit_folder(id));

-- Folder Grants Policies

-- R4: Users can see grants given to them
create policy "folder_grants_select_self" on public.folder_grants
for select
to authenticated
using (user_id = auth.uid());

-- R4: Owners (direct or ancestral) can see all grants on a folder
create policy "folder_grants_select_owner" on public.folder_grants
for select
to authenticated
using (public.has_folder_access(folder_id, false));

-- R3: Only owners (direct or ancestral) can add/remove grants
create policy "folder_grants_manage" on public.folder_grants
for all
to authenticated
using (public.has_folder_access(folder_id, true))
with check (public.has_folder_access(folder_id, true));

-- Documents Policies

-- R1: Select documents if user has read access to the folder
create policy "documents_select_access" on public.documents
for select
to authenticated
using (public.has_folder_access(folder_id, false));

-- R2: Insert documents if user can edit the folder
create policy "documents_insert_access" on public.documents
for insert
to authenticated
with check (public.can_edit_folder(folder_id));

-- R2: Update documents (including moving) if user can edit the OLD folder and the NEW folder
create policy "documents_update_access" on public.documents
for update
to authenticated
using (public.can_edit_folder(folder_id))
with check (public.can_edit_folder(folder_id));

-- R2: Delete documents if user can edit the folder
create policy "documents_delete_access" on public.documents
for delete
to authenticated
using (public.can_edit_folder(folder_id));

-- R5: Anonymous users have no access (default deny, but explicit revoke for clarity if needed, though RLS defaults to deny)
-- No policies created for 'anon' role implies deny all.

-- R6: Service role bypasses RLS automatically in Postgres/Supabase, no specific policy needed.
-- Ensure service_role has full grants on tables (usually default, but explicit for safety)
grant all on public.folders to service_role;
grant all on public.folder_grants to service_role;
grant all on public.documents to service_role;
grant usage on all sequences in schema public to service_role;

-- Revoke direct table access from authenticated to force RLS usage (optional but good practice, 
-- though RLS policies already restrict rows. Functions are security definer so they work).
-- Note: In Supabase, authenticated users usually need SELECT/INSERT etc privileges on the table 
-- in addition to RLS policies. The policies above handle the row filtering.
-- We ensure authenticated role has basic table privileges to interact, filtered by RLS.
grant usage on schema public to authenticated;
grant select, insert, update, delete on public.folders to authenticated;
grant select, insert, update, delete on public.folder_grants to authenticated;
grant select, insert, update, delete on public.documents to authenticated;
grant usage on all sequences in schema public to authenticated;
