  for insert
  with check (false);

create policy "no_update_approvals" on public.access_approvals
  for update
  using (false);

create policy "no_delete_approvals" on public.access_approvals
  for delete
  using (false);

-- R4: approve_access function
create function public.approve_access(p_request_id bigint) returns text as $$
declare
  v_requester_id uuid;
  v_status text;
  v_approval_count int;
begin
  -- Check if caller is authenticated
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  -- Check if caller is ops team member
  if not public.is_ops_team_member() then
    raise exception 'Caller is not an ops team member';
  end if;

  -- Get request details
  select requester_id, status into v_requester_id, v_status
  from public.access_requests
  where id = p_request_id;

  -- Check if request exists
  if not found then
    raise exception 'Request does not exist';
  end if;

  -- Check if request is pending
  if v_status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  -- Check if caller made the request
  if v_requester_id = auth.uid() then
    raise exception 'Requester cannot approve their own request';
  end if;

  -- Check if caller has already approved
  if exists (
    select 1 from public.access_approvals
    where request_id = p_request_id
    and approver_id = auth.uid()
  ) then
    raise exception 'Caller has already approved this request';
  end if;

  -- Record the approval
  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, auth.uid(), now());

  -- Count distinct approvers
  select count(distinct approver_id) into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  -- If two different ops team members have approved, set status to granted
  if v_approval_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    return 'granted';
  end if;

  return 'pending';
end;
$$ language plpgsql security definer;

-- R5: Anonymous visitors cannot see or change anything (handled by policy conditions checking auth.role() = 'authenticated')

-- R6: Service role bypasses RLS by default in Supabase, no additional policies needed

