grant usage on schema public to anon, authenticated;
grant select on public.ops_team to authenticated;
grant select, insert, delete on public.access_requests to authenticated;
grant select on public.access_approvals to authenticated;
grant execute on function public.approve_access(bigint) to authenticated;
grant execute on function public.is_ops_team_member() to authenticated;
