-- Helper function to check if current user is ops team
create or replace function public.is_ops_team()
returns boolean as $$
  select exists (
    select 1 from public.ops_team where user_id = auth.uid()
  );
$$ language sql security definer;

-- R1: Requesters see own requests/approvals; Ops team sees all; Signed-in users see ops team list
create policy "ops_team_select" on public.ops_team
  for select
  to authenticated
  using (true);

create policy "requests_select_own_or_ops" on public.access_requests
  for select
  to authenticated
  using (
    requester_id = auth.uid() OR public.is_ops_team()
  );

create policy "approvals_select_own_request_or_ops" on public.access_approvals
  for select
  to authenticated
  using (
    exists (
      select 1 from public.access_requests ar
      where ar.id = access_approvals.request_id
        and (ar.requester_id = auth.uid() OR public.is_ops_team())
    )
  );

-- R2: Signed-in users can create requests; Requesters can delete own pending requests
create policy "requests_insert" on public.access_requests
  for insert
  to authenticated
  with check (
    requester_id = auth.uid() AND status = 'pending'
  );

create policy "requests_delete_own_pending" on public.access_requests
  for delete
  to authenticated
  using (
    requester_id = auth.uid() AND status = 'pending'
  );

-- R3: Nobody can update requests or manipulate approvals directly (except via RPC)
-- Explicitly deny updates/deletes on requests for everyone (service_role bypasses RLS anyway)
create policy "requests_no_update" on public.access_requests
  for update
  to authenticated
  using (false);

create policy "approvals_no_insert" on public.access_approvals
  for insert
  to authenticated
  with check (false);

create policy "approvals_no_update" on public.access_approvals
  for update
  to authenticated
  using (false);

create policy "approvals_no_delete" on public.access_approvals
  for delete
  to authenticated
  using (false);

-- R4: approve_access function
create or replace function public.approve_access(p_request_id bigint)
returns text as $$
declare
  v_status text;
  v_requester_id uuid;
  v_approval_count int;
begin
  -- Validate caller is ops team
  if not public.is_ops_team() then
    raise exception 'Caller is not a member of the ops team';
  end if;

  -- Lock the request row and fetch details
  select status, requester_id
  into v_status, v_requester_id
  from public.access_requests
  where id = p_request_id
  for update;

  -- Check request exists
  if not found then
    raise exception 'Request not found';
  end if;

  -- Check request is pending
  if v_status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  -- Check caller is not the requester
  if v_requester_id = auth.uid() then
    raise exception 'Requesters cannot approve their own requests';
  end if;

  -- Check caller hasn't already approved
  if exists (
    select 1 from public.access_approvals
    where request_id = p_request_id AND approver_id = auth.uid()
  ) then
    raise exception 'Caller has already approved this request';
  end if;

  -- Insert approval
  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, auth.uid(), now());

  -- Count distinct approvers
  select count(distinct approver_id)
  into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  -- If 2 approvals, grant access
  if v_approval_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    return 'granted';
  end if;

  return 'pending';
end;
$$ language plpgsql security definer;

-- Revoke direct access on approvals from public/authenticated to enforce R3 strictly via RPC
revoke all on public.access_approvals from authenticated;
revoke all on public.access_approvals from anon;
grant select on public.access_approvals to authenticated; -- Re-grant select for R1 visibility via policy

-- Ensure anon has no access (R5)
revoke all on public.ops_team from anon;
revoke all on public.access_requests from anon;
revoke all on public.access_approvals from anon;
```

