);

-- R2: Signed-in users can create requests as themselves
create policy "access_requests_insert_authenticated"
on public.access_requests
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

-- R2: Requesters can withdraw (delete) their own pending requests
create policy "access_requests_delete_own_pending"
on public.access_requests
for delete
to authenticated
using (
  requester_id = auth.uid()
  and status = 'pending'
);

-- R1: Requesters can see approvals on their requests; Ops can see all approvals
create policy "access_approvals_select_own_request_or_ops"
on public.access_approvals
for select
to authenticated
using (
  exists (
    select 1 from public.access_requests ar
    where ar.id = request_id
    and (ar.requester_id = auth.uid() OR exists (select 1 from public.ops_team where user_id = auth.uid()))
  )
);

-- R3: Nobody can change requests, or create/change/delete approvals directly
-- We rely on the absence of UPDATE/INSERT/DELETE policies for access_approvals
-- and the absence of UPDATE policy for access_requests to enforce this.
-- Only the function approve_access will handle approvals.

-- Helper function to check if user is ops team
create or replace function public.is_ops_team_member()
returns boolean
language sql
security definer
stable
as $$
  select exists (select 1 from public.ops_team where user_id = auth.uid());
$$;

-- R4: approve_access function
create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_requester_id uuid;
  v_status text;
  v_approval_count int;
begin
  -- Check if caller is ops team
  if not public.is_ops_team_member() then
    raise exception 'Caller is not a member of the ops team';
  end if;

  -- Get request details
  select requester_id, status
  into v_requester_id, v_status
  from public.access_requests
  where id = p_request_id;

  -- Check if request exists
  if not found then
    raise exception 'Request does not exist';
  end if;

  -- Check if request is pending
  if v_status != 'pending' then
    raise exception 'Request is not pending';
  end if;

  -- Check if caller made the request
  if v_requester_id = auth.uid() then
    raise exception 'Caller cannot approve their own request';
  end if;

  -- Check if caller has already approved
  if exists (
    select 1 from public.access_approvals
    where request_id = p_request_id
    and approver_id = auth.uid()
  ) then
    raise exception 'Caller has already approved this request';
  end if;

  -- Record the approval
  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, auth.uid(), now());

  -- Count distinct approvers
  select count(distinct approver_id)
  into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  -- If two different ops members have approved, set status to granted
  if v_approval_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    return 'granted';
  end if;

  return 'pending';
end;
$$;

-- Grant execute on the function to authenticated users (ops team logic handled inside)
grant execute on function public.approve_access(bigint) to authenticated;

-- Revoke direct modifications to ensure R3
revoke update on table public.access_requests from authenticated;
revoke insert, update, delete on table public.access_approvals from authenticated;
```

