on public.providers
for select
to authenticated
using (true);

create policy "slots_select_patients_and_providers"
on public.slots
for select
to authenticated
using (
  -- Providers see their own slots
  (public.is_provider() AND provider_id = auth.uid())
  OR
  -- Patients see open future slots OR slots they booked
  (
    NOT public.is_provider()
    AND (
      (booked_by IS NULL AND starts_at > now())
      OR
      (booked_by = auth.uid())
    )
  )
);

create policy "slots_update_book_self"
on public.slots
for update
to authenticated
with check (
  -- Allow update only if:
  -- 1. It's a patient (not a provider)
  -- 2. The slot is in the future
  -- 3. The slot was previously unbooked OR booked by the current user
  -- 4. The new state is either booking for self OR canceling own booking
  NOT public.is_provider()
  AND starts_at > now()
  AND (booked_by IS NULL OR booked_by = auth.uid())
  AND (booked_by = auth.uid() OR booked_by IS NULL)
);

-- Explicitly deny anonymous access (default is deny, but explicit for clarity on R6)
create policy "slots_deny_anon"
on public.slots
for all
to anon
using (false);

create policy "providers_deny_anon"
on public.providers
for all
to anon
using (false);

