create function public.is_project_member(target_project_id bigint, required_role text default null)
returns boolean as $$
  select exists (
    select 1 from public.project_members pm
    where pm.project_id = target_project_id
      and pm.user_id = auth.uid()
      and (required_role is null or pm.role = required_role)
  );
$$ language sql security definer stable;

create function public.get_user_role_in_project(target_project_id bigint)
returns text as $$
  select pm.role from public.project_members pm
  where pm.project_id = target_project_id and pm.user_id = auth.uid();
$$ language sql security definer stable;

create function public.can_see_issue(rec public.issues)
returns boolean as $$
declare
  user_role text;
begin
  if not public.is_project_member(rec.project_id) then
    return false;
  end if;

  if not rec.is_confidential then
    return true;
  end if;

  user_role := public.get_user_role_in_project(rec.project_id);

  if user_role = 'maintainer' then
    return true;
  end if;

  if rec.reporter_id = auth.uid() or rec.assignee_id = auth.uid() then
    return true;
  end if;

  return false;
end;
$$ language plpgsql security definer stable;

create policy "Members can view their projects"
on public.projects
for select
to authenticated
using (
  public.is_project_member(id)
);

create policy "Members can view project members in their projects"
on public.project_members
for select
to authenticated
using (
  public.is_project_member(project_id)
);

create policy "Members can view issues based on confidentiality rules"
on public.issues
for select
to authenticated
using (
  public.can_see_issue(public.issues)
);

create policy "Members can insert issues in their projects"
on public.issues
for insert
to authenticated
with check (
  public.is_project_member(project_id)
  and reporter_id = auth.uid()
  and status = 'open'
);

create policy "Developers and maintainers can update visible issues"
on public.issues
for update
to authenticated
using (
  public.can_see_issue(public.issues)
  and public.get_user_role_in_project(project_id) in ('developer', 'maintainer')
)
with check (
  public.can_see_issue(public.issues)
  and public.get_user_role_in_project(project_id) in ('developer', 'maintainer')
  and (
    case
      when public.get_user_role_in_project(project_id) = 'maintainer' then true
      else (old.is_confidential = new.is_confidential)
    end
  )
  and (old.project_id = new.project_id)
);

