-- Enable RLS on all tables
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.issues enable row level security;

-- Helper function to check if user is a member of a project
create or replace function public.is_project_member(proj_id bigint, required_role text default null)
returns boolean as $$
declare
  user_role text;
begin
  if auth.uid() is null then
    return false;
  end if;

  select pm.role into user_role
  from public.project_members pm
  where pm.project_id = proj_id 
    and pm.user_id = auth.uid();

  if required_role is null then
    return user_role is not null;
  else
    return user_role = required_role;
  end if;
end;
$$ language plpgsql security definer;

-- Helper function to check if user can see a specific issue
create or replace function public.can_see_issue(issue_row public.issues)
returns boolean as $$
declare
  user_role text;
begin
  if auth.uid() is null then
    return false;
  end if;

  -- Get user's role in the project
  select pm.role into user_role
  from public.project_members pm
  where pm.project_id = issue_row.project_id 
    and pm.user_id = auth.uid();

  if user_role is null then
    return false;
  end if;

  -- Non-confidential issues: visible to all members
  if not issue_row.is_confidential then
    return true;
  end if;

  -- Confidential issues: visible to maintainers, reporter, or assignee
  if user_role = 'maintainer' then
    return true;
  end if;

  if issue_row.reporter_id = auth.uid() then
    return true;
  end if;

  if issue_row.assignee_id = auth.uid() then
    return true;
  end if;

  return false;
end;
$$ language plpgsql security definer;

-- Projects policies
create policy "Members can view their projects"
on public.projects
for select
using (
  public.is_project_member(id)
);

-- Project members policies
create policy "Members can view project members in their projects"
on public.project_members
for select
using (
  public.is_project_member(project_id)
);

-- Issues policies
create policy "Members can view issues according to confidentiality rules"
on public.issues
for select
using (
  public.can_see_issue(issues)
);

create policy "Members can insert issues in their projects"
on public.issues
for insert
with check (
  public.is_project_member(project_id) 
  and reporter_id = auth.uid()
  and status = 'open'
);

create policy "Developers and maintainers can update issues they can see"
on public.issues
for update
using (
  public.can_see_issue(issues)
  and public.is_project_member(project_id, 'developer')
  or public.is_project_member(project_id, 'maintainer')
)
with check (
  -- Prevent changing project_id
  project_id = (select project_id from public.issues where id = issues.id)
  -- Prevent reporters from updating (already handled by role check in USING)
  -- Prevent non-maintainers from changing confidentiality
  and (
    public.is_project_member(project_id, 'maintainer')
    or is_confidential = (select is_confidential from public.issues where id = issues.id)
  )
);

-- Revoke all permissions from anon
revoke all on table public.projects from anon;
revoke all on table public.project_members from anon;
revoke all on table public.issues from anon;

-- Grant authenticated users usage on helper functions
grant execute on function public.is_project_member to authenticated;
grant execute on function public.can_see_issue to authenticated;
