-- Enable RLS
alter table public.documents enable row level security;
alter table public.doc_access enable row level security;

-- Helper function to check if user has edit access to a document
create or replace function public.has_edit_access(p_doc_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.doc_access
    where doc_id = p_doc_id
      and user_id = auth.uid()
      and can_edit = true
  );
$$ language sql security definer stable;

-- R1: Users can read documents they have access to
create policy "users_can_read_accessible_documents"
on public.documents
for select
to authenticated
using (
  exists (
    select 1 from public.doc_access
    where doc_id = id
      and user_id = auth.uid()
  )
);

-- R1: Users can read their own access rows
create policy "users_can_read_own_access"
on public.doc_access
for select
to authenticated
using (user_id = auth.uid());

-- R2: No direct inserts/updates/deletes on documents or doc_access for authenticated users
create policy "no_direct_document_modifications"
on public.documents
for all
to authenticated
using (false)
with check (false);

create policy "no_direct_access_modifications"
on public.doc_access
for all
to authenticated
using (false)
with check (false);

-- R5: Anonymous users cannot see or change anything (explicit deny, though default is deny)
create policy "deny_anon_documents"
on public.documents
for all
to anon
using (false)
with check (false);

create policy "deny_anon_access"
on public.doc_access
for all
to anon
using (false)
with check (false);

-- R3 & R4: Checkout function
create or replace function public.checkout_document(p_doc_id bigint)
returns void as $$
declare
  v_current_holder uuid;
  v_user_id uuid := auth.uid();
begin
  -- Check if user exists and is authenticated
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  -- Check if document exists and user has edit access
  if not public.has_edit_access(p_doc_id) then
    raise exception 'Access denied: user does not have edit access to this document';
  end if;

  -- Get current holder
  select checked_out_by into v_current_holder
  from public.documents
  where id = p_doc_id;

  -- If document doesn't exist
  if not found then
    raise exception 'Document not found';
  end if;

  -- If someone else has it checked out
  if v_current_holder is not null and v_current_holder != v_user_id then
    raise exception 'Document is currently checked out by another user';
  end if;

  -- Lock the document (idempotent if already held by same user)
  update public.documents
  set checked_out_by = v_user_id
  where id = p_doc_id;
end;
$$ language plpgsql security definer;

-- R4: Checkin function
create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void as $$
declare
  v_current_holder uuid;
  v_user_id uuid := auth.uid();
begin
  -- Check if user exists and is authenticated
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  -- Get current holder
  select checked_out_by into v_current_holder
  from public.documents
  where id = p_doc_id;

  -- If document doesn't exist
  if not found then
    raise exception 'Document not found';
  end if;

  -- If caller doesn't have the document checked out
  if v_current_holder is null or v_current_holder != v_user_id then
    raise exception 'Cannot check in: document is not checked out by you';
  end if;

  -- Update body and release lock
  update public.documents
  set body = p_body,
      checked_out_by = null
  where id = p_doc_id;
end;
$$ language plpgsql security definer;

-- Grant execute permissions on functions to authenticated users
grant execute on function public.checkout_document(bigint) to authenticated;
grant execute on function public.checkin_document(bigint, text) to authenticated;

-- Ensure service_role bypasses RLS (default behavior, but explicit for clarity)
-- No additional policies needed for service_role as it bypasses RLS by default
