alter table public.pastes enable row level security;

create function public.is_paste_visible(paste_row public.pastes)
returns boolean as $$
begin
  -- Rule R1: Anyone can read public, non-expired pastes
  if paste_row.is_private = false and (paste_row.expires_at is null or paste_row.expires_at > now()) then
    return true;
  end if;

  -- Rule R2: Signed-in authors can read their own private/expired pastes
  if auth.uid() is not null and paste_row.author_id = auth.uid() then
    return true;
  end if;

  return false;
end;
$$ language plpgsql security definer;

create policy "select_public_and_owned"
on public.pastes
for select
using (
  public.is_paste_visible(pastes)
);

create policy "insert_anyone"
on public.pastes
for insert
with check (
  -- Rule R3: Anyone can create.
  -- If signed in, author_id must be self (or default handles it).
  -- If anonymous, author_id must be null and is_private must be false.
  case
    when auth.uid() is null then
      (author_id is null and is_private = false)
    else
      (author_id = auth.uid())
  end
);

create policy "delete_owned"
on public.pastes
for delete
using (
  -- Rule R4: Authors can delete their own pastes.
  author_id = auth.uid()
);

-- Explicitly revoke update for everyone to enforce "Nobody can edit"
revoke update on public.pastes from anon, authenticated;
