```sql
-- Enable RLS on all tables
alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

-- Helper function to check if current user is staff for a given building_id
create or replace function public.is_building_staff(target_building_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.building_staff bs
    where bs.building_id = target_building_id
      and bs.user_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check if current user is a resident of a given unit_id
create or replace function public.is_unit_resident(target_unit_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.residents r
    where r.unit_id = target_unit_id
      and r.user_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to get building_id from unit_id
create or replace function public.get_building_id_from_unit(target_unit_id bigint)
returns bigint as $$
  select u.building_id from public.units u where u.id = target_unit_id;
$$ language sql security definer;

-- POLICIES: public.units
-- R1: Residents see own units; Staff see units in their buildings
create policy "units_select_residents_and_staff" on public.units
  for select
  to authenticated
  using (
    public.is_unit_resident(id) OR public.is_building_staff(building_id)
  );

-- R5: No updates/inserts/deletes on units via app
create policy "units_no_modifications" on public.units
  for all
  to authenticated
  using (false)
  with check (false);

-- POLICIES: public.residents
-- R5: Users can see their own residence rows; Staff can see all residents in their buildings
create policy "residents_select_own_and_staff" on public.residents
  for select
  to authenticated
  using (
    user_id = auth.uid() OR public.is_building_staff(
      (select u.building_id from public.units u where u.id = residents.unit_id)
    )
  );

-- R5: No modifications
create policy "residents_no_modifications" on public.residents
  for all
  to authenticated
  using (false)
  with check (false);

-- POLICIES: public.building_staff
-- R5: Users can see their own staff rows
create policy "staff_select_own" on public.building_staff
  for select
  to authenticated
  using (user_id = auth.uid());

-- R5: No modifications
create policy "staff_no_modifications" on public.building_staff
  for all
  to authenticated
  using (false)
  with check (false);

-- POLICIES: public.requests
-- R1: Residents see requests for their units; Staff see all requests in their buildings
create policy "requests_select_residents_and_staff" on public.requests
  for select
  to authenticated
  using (
    public.is_unit_resident(unit_id) OR public.is_building_staff(
      (select u.building_id from public.units u where u.id = requests.unit_id)
    )
  );

-- R2: Residents can create requests for their own units as themselves
create policy "requests_insert_residents" on public.requests
  for insert
  to authenticated
  with check (
    public.is_unit_resident(unit_id) AND
    created_by = auth.uid() AND
    status = 'open'
  );

-- R4: Staff can update status only; Nobody else can update anything
create policy "requests_update_status_staff_only" on public.requests
  for update
  to authenticated
  using (
    public.is_building_staff(
      (select u.building_id from public.units u where u.id = requests.unit_id)
    )
  )
  with check (
    public.is_building_staff(
      (select u.building_id from public.units u where u.id = requests.unit_id)
    ) AND
    id = requests.id AND
    unit_id = requests.unit_id AND
    created_by = requests.created_by AND
    description = requests.description AND
    status in ('open', 'in_progress', 'done')
  );

-- R4: No deletes
create policy "requests_no_delete" on public.requests
  for delete
  to authenticated
  using (false);

-- POLICIES: public.request_photos
-- R1/R3: Residents see photos for their units; Staff see photos for their buildings
create policy "request_photos_select_residents_and_staff" on public.request_photos
  for select
  to authenticated
  using (
    exists (
      select 1 from public.requests req
      join public.units u on u.id = req.unit_id
      where req.id = request_photos.request_id
        and (public.is_unit_resident(req.unit_id) OR public.is_building_staff(u.building_id))
    )
  );

-- R3: Residents and Staff can add photos to requests they can see
create policy "request_photos_insert_residents_and_staff" on public.request_photos
  for insert
  to authenticated
  with check (
    exists (
      select 1 from public.requests req
      join public.units u on u.id = req.unit_id
      where req.id = request_photos.request_id
        and (public.is_unit_resident(req.unit_id) OR public.is_building_staff(u.building_id))
    )
  );

-- R3/R4: No updates or deletes on photos (append-only based on rules, though not explicitly forbidden, standard practice for audit trails unless specified. Rules say "add photos", "Nobody can change anything else about a request". Assuming photos are immutable once added to prevent tampering with evidence, or at least no update policy defined implies default deny if not created. Explicitly denying update/delete to be safe per "Nobody can change anything else" spirit regarding request integrity).
-- Actually, R3 says "add photos". R4 says "Nobody can change anything else about a request". Photos are linked to requests. Let's strictly follow "add". Updates/Deletes not mentioned as allowed.
create policy "request_photos_no_update" on public.request_photos
  for update
  to authenticated
  using (false)
  with check (false);

create policy "request_photos_no_delete" on public.request_photos
  for delete
  to authenticated
  using (false);

-- R6: Anonymous users (anon) have no access (default deny when no policies match, but explicit deny for clarity if needed, though Supabase defaults to no access if no policy permits. We rely on no policies for 'anon' role).
-- Ensure no policies exist for 'anon' role (none created above).

-- R7: Service role bypasses RLS automatically in Postgres/Supabase, no specific policy needed.

-- Grants for authenticated users to use helper functions
grant execute on function public.is_building_staff(bigint) to authenticated;
grant execute on function public.is_unit_resident(bigint) to authenticated;
grant execute on function public.get_building_id_from_unit(bigint) to authenticated;

-- Revoke direct access to tables from anon just in case (default is usually no access, but explicit)
revoke all on table public.units from anon;
revoke all on table public.residents from anon;
revoke all on table public.building_staff from anon;
revoke all on table public.requests from anon;
revoke all on table public.request_photos from anon;

-- Grant usage to authenticated
grant usage on schema public to authenticated;
grant select, insert, update, delete on table public.units to authenticated; -- Policies restrict actual rows
grant select, insert, update, delete on table public.residents to authenticated;
grant select, insert, update, delete on table public.building_staff to authenticated;
grant select, insert, update, delete on table public.requests to authenticated;
grant select, insert, update, delete on table public.request_photos to authenticated;

-- Grant sequence usage for identity columns
grant usage, select on all sequences in schema public to authenticated;
