```sql
-- Enable RLS
alter table public.courses enable row level security;
alter table public.enrollments enable row level security;
alter table public.threads enable row level security;
alter table public.posts enable row level security;

-- Helper function to check if user is a member of a course
create or replace function public.is_course_member(target_course_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.enrollments
    where course_id = target_course_id
      and user_id = auth.uid()
  );
$$ language sql security definer;

-- Helper function to check if user is a TA for a course
create or replace function public.is_course_ta(target_course_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.enrollments
    where course_id = target_course_id
      and user_id = auth.uid()
      and role = 'ta'
  );
$$ language sql security definer;

-- Helper function to check if thread is unlocked
create or replace function public.is_thread_unlocked(target_thread_id bigint)
returns boolean as $$
  select not is_locked from public.threads where id = target_thread_id;
$$ language sql security definer;

-- COURSES POLICIES
-- R1: Members can see their courses
create policy "members_view_courses" on public.courses
  for select
  to authenticated
  using (public.is_course_member(id));

-- R5: Nobody can change courses
create policy "no_update_courses" on public.courses
  for update
  to authenticated
  using (false);

create policy "no_insert_courses" on public.courses
  for insert
  to authenticated
  with check (false);

create policy "no_delete_courses" on public.courses
  for delete
  to authenticated
  using (false);

-- ENROLLMENTS POLICIES
-- R1: Members can see their own enrollment rows
create policy "members_view_own_enrollment" on public.enrollments
  for select
  to authenticated
  using (user_id = auth.uid());

-- R5: Nobody can change enrollments
create policy "no_update_enrollments" on public.enrollments
  for update
  to authenticated
  using (false);

create policy "no_insert_enrollments" on public.enrollments
  for insert
  to authenticated
  with check (false);

create policy "no_delete_enrollments" on public.enrollments
  for delete
  to authenticated
  using (false);

-- THREADS POLICIES
-- R1: Members can see every thread in their courses
create policy "members_view_threads" on public.threads
  for select
  to authenticated
  using (public.is_course_member(course_id));

-- R2: Members can start unlocked threads in their courses
create policy "members_insert_threads" on public.threads
  for insert
  to authenticated
  with check (
    public.is_course_member(course_id)
    and created_by = auth.uid()
    and is_locked = false
  );

-- R4: TAs can lock/unlock threads; R5: Others cannot update threads (including students)
create policy "ta_update_threads" on public.threads
  for update
  to authenticated
  using (public.is_course_ta(course_id))
  with check (public.is_course_ta(course_id));

-- R4/R5: Prevent students from updating threads (explicit deny via separate policy or handled by above)
-- Since 'ta_update_threads' only allows TAs, students are implicitly denied UPDATE.
-- However, we must ensure no other update policy exists. The default is deny if no policy matches.

-- R4: TAs can delete any post (handled in posts), but can they delete threads? 
-- Rules say "delete any post in them", not explicitly threads. 
-- Assuming threads are not deletable by users based on "Nobody can change courses or enrollments" spirit 
-- and lack of explicit thread deletion rule for users. 
-- Default deny for delete unless specified.
create policy "no_delete_threads" on public.threads
  for delete
  to authenticated
  using (false);

-- POSTS POLICIES
-- R1: Members can see every post in their courses (join through thread)
create policy "members_view_posts" on public.posts
  for select
  to authenticated
  using (
    exists (
      select 1 from public.threads t
      where t.id = thread_id
        and public.is_course_member(t.course_id)
    )
  );

-- R2: Members can write posts in unlocked threads of their courses
create policy "members_insert_posts" on public.posts
  for insert
  to authenticated
  with check (
    author_id = auth.uid()
    and exists (
      select 1 from public.threads t
      where t.id = thread_id
        and public.is_course_member(t.course_id)
        and not t.is_locked
    )
  );

-- R3: Authors can edit/delete own posts only while thread is unlocked
create policy "authors_update_posts" on public.posts
  for update
  to authenticated
  using (
    author_id = auth.uid()
    and public.is_thread_unlocked(thread_id)
  )
  with check (
    author_id = auth.uid()
    and public.is_thread_unlocked(thread_id)
  );

create policy "authors_delete_posts" on public.posts
  for delete
  to authenticated
  using (
    author_id = auth.uid()
    and public.is_thread_unlocked(thread_id)
  );

-- R4: TAs can delete any post in their courses
create policy "ta_delete_posts" on public.posts
  for delete
  to authenticated
  using (
    exists (
      select 1 from public.threads t
      where t.id = thread_id
        and public.is_course_ta(t.course_id)
    )
  );

-- R6: Anonymous visitors cannot see or change anything (default deny for anon, explicit revoke if needed)
-- Supabase anon role is 'anon'. By default, if no policy matches, access is denied.
-- Ensure no policies grant access to 'anon'. The policies above are all 'to authenticated'.

-- GRANTS
-- Revoke all public access on these tables to ensure RLS is the only gate
revoke all on public.courses from anon, authenticated;
revoke all on public.enrollments from anon, authenticated;
revoke all on public.threads from anon, authenticated;
revoke all on public.posts from anon, authenticated;

-- Grant usage to authenticated role (RLS will filter rows)
grant usage on schema public to authenticated;
grant select on public.courses to authenticated;
grant select on public.enrollments to authenticated;
grant select, insert, update, delete on public.threads to authenticated;
grant select, insert, update, delete on public.posts to authenticated;

-- Note: service_role bypasses RLS automatically in Supabase, so no explicit grants needed for it beyond default superuser status.
