```sql
alter table public.items enable row level security;
alter table public.claims enable row level security;

-- Helper function to get the finder of an item
create or replace function public.get_item_finder(p_item_id bigint)
returns uuid as $$
  select found_by from public.items where id = p_item_id;
$$ language sql security definer;

-- Helper function to check if an item already has an approved claim
create or replace function public.item_has_approved_claim(p_item_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.claims
    where item_id = p_item_id and status = 'approved'
  );
$$ language sql security definer;

-- R1: Signed-in users can see every item.
create policy "authenticated_users_select_items"
on public.items
for select
to authenticated
using (true);

-- R1: Finders can post items as themselves (always 'open').
create policy "authenticated_users_insert_items"
on public.items
for insert
to authenticated
with check (
  found_by = auth.uid()
  and status = 'open'
);

-- R1: Finders can change their own items.
create policy "finders_update_items"
on public.items
for update
to authenticated
using (found_by = auth.uid());

-- R5: Anonymous visitors cannot see or change anything (explicit deny by omission, but adding explicit false for clarity on select if needed, though default is no access without policy).
-- No policies created for 'anon' role, so they have no access by default.

-- R2: Claimants can see their own claims.
create policy "claimants_select_own_claims"
on public.claims
for select
to authenticated
using (claimant_id = auth.uid());

-- R2: Finders can see every claim on their items.
create policy "finders_select_claims_on_their_items"
on public.claims
for select
to authenticated
using (
  item_id in (
    select id from public.items where found_by = auth.uid()
  )
);

-- R3: Users can claim open items they did not find, as themselves; new claims are always 'pending'.
create policy "authenticated_users_insert_claims"
on public.claims
for insert
to authenticated
with check (
  claimant_id = auth.uid()
  and status = 'pending'
  and exists (
    select 1 from public.items
    where id = item_id
      and status = 'open'
      and found_by != auth.uid()
  )
);

-- R4: Only the finder can approve or reject a pending claim on their item.
-- R4: Claimants can never change a claim's status.
-- R4: Nothing else about a claim can change.
create policy "finders_update_claim_status"
on public.claims
for update
to authenticated
using (
  -- User must be the finder of the item associated with the claim
  exists (
    select 1 from public.items
    where id = item_id and found_by = auth.uid()
  )
  -- Can only update if status is currently pending
  and status = 'pending'
)
with check (
  -- Ensure the item still belongs to the finder (防 race condition)
  exists (
    select 1 from public.items
    where id = item_id and found_by = auth.uid()
  )
  -- Ensure status transitions only to approved or rejected
  and status in ('approved', 'rejected')
  -- Ensure no other fields change by comparing old and new values via trigger or restricting columns?
  -- Since WITH CHECK validates the NEW row, and USING validates the OLD row,
  -- we must ensure other columns haven't changed.
  -- However, standard SQL policies cannot easily compare OLD vs NEW for specific columns without a trigger.
  -- But we can enforce that the claimant_id and message and item_id remain the same as the original
  -- by relying on the fact that the user shouldn't be able to provide different values if they don't know them?
  -- No, a malicious user could try to update message.
  -- To strictly enforce "nothing else about a claim can change", we need a trigger.
);

-- Trigger to enforce immutability of non-status fields and single approved claim constraint
create or replace function public.enforce_claim_rules()
returns trigger as $$
declare
  v_finder uuid;
  v_approved_count int;
begin
  -- R4: Nothing else about a claim can change (except status by finder)
  if tg_op = 'UPDATE' then
    if old.claimant_id != new.claimant_id
       or old.item_id != new.item_id
       or old.message != new.message then
      raise exception 'Cannot modify claim details';
    end if;

    -- Get finder
    select found_by into v_finder from public.items where id = new.item_id;

    -- R4: Only finder can change status
    if old.status != new.status then
      if auth.uid() != v_finder then
        raise exception 'Only the finder can update claim status';
      end if;

      -- R4: Status must go from pending to approved/rejected
      if old.status != 'pending' then
        raise exception 'Can only update pending claims';
      end if;

      -- R4: At most one approved claim per item
      if new.status = 'approved' then
        select count(*) into v_approved_count
        from public.claims
        where item_id = new.item_id
          and status = 'approved'
          and id != new.id; -- Exclude current row if it's being updated to approved (though it was pending before)

        if v_approved_count > 0 then
          raise exception 'Item already has an approved claim';
        end if;
      end if;
    end if;
  end if;

  -- R3/R4: Insert checks (mostly covered by policy, but double check single approved claim on insert? No, inserts are always pending)
  if tg_op = 'INSERT' then
    if new.status != 'pending' then
      raise exception 'New claims must be pending';
    end if;
    if new.claimant_id != auth.uid() then
      raise exception 'Claimant ID must match current user';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

create trigger trigger_enforce_claim_rules
before insert or update on public.claims
for each row execute procedure public.enforce_claim_rules();

-- R6: Service role bypasses RLS by default in Supabase, no explicit policy needed.
-- Grants for authenticated users to use the tables
grant usage on schema public to authenticated;
grant select, insert, update on public.items to authenticated;
grant select, insert, update on public.claims to authenticated;
grant usage on all sequences in schema public to authenticated;

-- Revoke from anon explicitly to be safe (though no policies exist)
revoke all on public.items from anon;
revoke all on public.claims from anon;
```

