  on public.orders
  for insert
  to authenticated
  with check (
    auth.uid() = buyer_id
    and auth.uid() != seller_id
    and status = 'pending_payment'
    and exists (
      select 1
      from public.listings l
      where l.id = listing_id
        and l.seller_id = orders.seller_id
        and l.price = orders.amount
    )
  );

