  on public.orders
  for all
  to authenticated
  using (false)
  with check (false);

create or replace function public.mark_shipped(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_seller_id uuid;
begin
  select status, seller_id
  into v_status, v_seller_id
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order not found';
  end if;

  if auth.uid() != v_seller_id then
    raise exception 'Only the seller can mark an order as shipped';
  end if;

  if v_status != 'paid' then
    raise exception 'Order must be in paid status to be marked as shipped';
  end if;

  update public.orders
  set status = 'shipped'
  where id = p_order_id;

  return 'shipped';
end;
$$;

create or replace function public.release_funds(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_buyer_id uuid;
begin
  select status, buyer_id
  into v_status, v_buyer_id
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order not found';
  end if;

  if auth.uid() != v_buyer_id then
    raise exception 'Only the buyer can release funds';
  end if;

  if v_status != 'shipped' then
    raise exception 'Order must be in shipped status to release funds';
  end if;

  update public.orders
  set status = 'released'
  where id = p_order_id;

  return 'released';
end;
$$;

create or replace function public.refund_order(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_seller_id uuid;
begin
  select status, seller_id
  into v_status, v_seller_id
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order not found';
  end if;

  if auth.uid() != v_seller_id then
    raise exception 'Only the seller can refund an order';
  end if;

  if v_status not in ('paid', 'shipped') then
    raise exception 'Order must be in paid or shipped status to be refunded';
  end if;

  update public.orders
  set status = 'refunded'
  where id = p_order_id;

  return 'refunded';
end;
$$;

