-- Helper function to mask email
create or replace function public.mask_email(email_text text)
returns text as $$
declare
  local_part text;
  domain_part text;
  first_char text;
begin
  if email_text is null then return null; end if;
  local_part := split_part(email_text, '@', 1);
  domain_part := split_part(email_text, '@', 2);
  first_char := left(local_part, 1);
  return first_char || '***@' || domain_part;
end;
$$ language plpgsql security definer;

-- Helper function to mask phone
create or replace function public.mask_phone(phone_text text)
returns text as $$
begin
  if phone_text is null then return null; end if;
  return '******' || right(phone_text, 4);
end;
$$ language plpgsql security definer;

