```sql
alter table public.journal_entries enable row level security;

create function public.check_entry_ownership()
returns boolean as $$
begin
  return auth.uid() = (select user_id from public.journal_entries where id = NEW.id);
end;
$$ language plpgsql security definer;

create function public.is_within_24_hours(entry_created_at timestamptz)
returns boolean as $$
begin
  return entry_created_at >= (now() - interval '24 hours');
end;
$$ language plpgsql security definer;

-- Policy for SELECT: Users can only read their own entries
create policy "Users can view own entries"
on public.journal_entries
for select
to authenticated
using (auth.uid() = user_id);

-- Policy for INSERT: Users can only insert their own entries, cannot set created_at manually
create policy "Users can insert own entries"
on public.journal_entries
for insert
to authenticated
with check (
  auth.uid() = user_id 
  and (NEW.created_at IS NULL OR NEW.created_at = now())
);

-- Policy for UPDATE: Users can only update their own entries within 24 hours, cannot change created_at
create policy "Users can update own entries within 24h"
on public.journal_entries
for update
to authenticated
using (
  auth.uid() = user_id 
  and public.is_within_24_hours(created_at)
)
with check (
  auth.uid() = user_id 
  and created_at = OLD.created_at
);

-- Policy for DELETE: Users can only delete their own entries within 24 hours
create policy "Users can delete own entries within 24h"
on public.journal_entries
for delete
to authenticated
using (
  auth.uid() = user_id 
  and public.is_within_24_hours(created_at)
);

-- Revoke all access from anon
revoke all on table public.journal_entries from anon;

-- Grant necessary permissions to authenticated users (policies restrict further)
grant select, insert, update, delete on table public.journal_entries to authenticated;
grant usage on sequence public.journal_entries_id_seq to authenticated;
