    where t.project_id = public.segments.project_id
    and t.lang = public.segments.lang
    and t.user_id = auth.uid()
  )
);

create policy "Translators can update draft segments in their language"
on public.segments
for update
to authenticated
using (
  status = 'draft'
  and exists (
    select 1 from public.translators t
    where t.project_id = public.segments.project_id
    and t.lang = public.segments.lang
    and t.user_id = auth.uid()
    and t.role = 'translator'
  )
)
with check (
  status = 'draft'
  and translated_by = auth.uid()
  and source_text = (select source_text from public.segments where id = public.segments.id)
);

create policy "Reviewers can update draft segments to reviewed"
on public.segments
for update
to authenticated
using (
  status = 'draft'
  and exists (
    select 1 from public.translators t
    where t.project_id = public.segments.project_id
    and t.lang = public.segments.lang
    and t.user_id = auth.uid()
    and t.role = 'reviewer'
  )
)
with check (
  status in ('draft', 'reviewed')
  and source_text = (select source_text from public.segments where id = public.segments.id)
);

create policy "Prevent source text changes and reviewed edits"
on public.segments
for update
to authenticated
using (
  source_text = (select source_text from public.segments where id = public.segments.id)
)
with check (
  source_text = (select source_text from public.segments where id = public.segments.id)
  and (
    status = 'reviewed'
    and (select status from public.segments where id = public.segments.id) = 'reviewed'
    and source_text = (select source_text from public.segments where id = public.segments.id)
    and target_text = (select target_text from public.segments where id = public.segments.id)
    and translated_by = (select translated_by from public.segments where id = public.segments.id)
  )
  or
  status != 'reviewed'
);

create policy "Anonymous users have no access"
on public.projects
for all
to anon
using (false)
with check (false);

create policy "Anonymous users have no access to translators"
on public.translators
for all
to anon
using (false)
with check (false);

