create function public.is_parent_of_household(p_household_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.household_members hm
    where hm.household_id = p_household_id
      and hm.user_id = auth.uid()
      and hm.role = 'parent'
  );
$$ language sql security definer stable;

create function public.is_member_of_household(p_household_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.household_members hm
    where hm.household_id = p_household_id
      and hm.user_id = auth.uid()
  );
$$ language sql security definer stable;

create function public.is_child_of_household(p_household_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.household_members hm
    where hm.household_id = p_household_id
      and hm.user_id = auth.uid()
      and hm.role = 'child'
  );
$$ language sql security definer stable;

create function public.check_chore_assignee_in_same_household()
returns trigger as $$
declare
  v_household_id bigint;
  v_assignee_role text;
begin
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.assignee_id is distinct from old.assignee_id) then
    select hm.household_id, hm.role
    into v_household_id, v_assignee_role
    from public.household_members hm
    where hm.user_id = new.assignee_id;

    if v_household_id is null then
      raise exception 'Assignee must be a member of a household';
    end if;

    if v_household_id != new.household_id then
      raise exception 'Assignee must belong to the same household as the chore';
    end if;

    if v_assignee_role != 'child' then
      raise exception 'Chores can only be assigned to children';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

create function public.enforce_chore_immutability_if_approved()
returns trigger as $$
begin
  if tg_op = 'UPDATE' and old.status = 'approved' then
    if new is distinct from old then
      raise exception 'Approved chores cannot be modified';
    end if;
  end if;

  if tg_op = 'DELETE' and old.status = 'approved' then
    raise exception 'Approved chores cannot be deleted';
  end if;

  return new;
end;
$$ language plpgsql security definer;

create function public.enforce_child_chore_update_restrictions()
returns trigger as $$
begin
  if auth.uid() in (select user_id from public.household_members where role = 'child' and household_id = new.household_id) then
    if new.status = 'approved' then
      raise exception 'Children cannot approve chores';
    end if;

    if new.title is distinct from old.title or
       new.points is distinct from old.points or
       new.assignee_id is distinct from old.assignee_id or
       new.household_id is distinct from old.household_id then
      raise exception 'Children can only update the status of their own chores to done';
    end if;

    if not (old.status = 'todo' and new.status = 'done') and new.status is distinct from old.status then
      raise exception 'Children can only change status from todo to done';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

