create function public.enforce_chore_update_rules()
returns trigger
language plpgsql
security definer
as $$
declare
  v_user_role text;
begin
  select hm.role
  into v_user_role
  from public.household_members hm
  where hm.household_id = new.household_id
    and hm.user_id = auth.uid();

  if v_user_role is null then
    raise exception 'User is not a member of this household';
  end if;

  if old.status = 'approved' then
    if new is distinct from old then
      raise exception 'Approved chores cannot be modified';
    end if;
    return new;
  end if;

  if v_user_role = 'child' then
    if new.assignee_id is distinct from old.assignee_id
       or new.title is distinct from old.title
       or new.points is distinct from old.points
       or new.household_id is distinct from old.household_id then
      raise exception 'Children can only update the status of their own chores';
    end if;

    if new.assignee_id != auth.uid() then
      raise exception 'Children can only update their own chores';
    end if;

    if old.status != 'todo' then
      raise exception 'Children can only mark todo chores as done';
    end if;

    if new.status not in ('todo', 'done') then
      raise exception 'Children can only set status to done';
    end if;

  elsif v_user_role = 'parent' then
    if new.status = 'approved' and old.status != 'approved' then
      -- Approval allowed
      null;
    elsif new.status != 'approved' and old.status != 'approved' then
      -- Editing allowed
      null;
    elsif old.status = 'approved' then
      raise exception 'Approved chores cannot be modified';
    else
      raise exception 'Invalid status transition for parent';
    end if;
  else
    raise exception 'Invalid role';
  end if;

  return new;
end;
$$;

