create function public.check_chore_household_membership()
returns trigger
language plpgsql
security definer
as $$
begin
  if not public.is_member_of_household(new.household_id) then
    raise exception 'User must be a member of the household to interact with its chores';
  end if;

  if tg_op = 'INSERT' then
    if not public.is_parent_of_household(new.household_id) then
      raise exception 'Only parents can create chores';
    end if;
    if new.status != 'todo' then
      raise exception 'New chores must have status "todo"';
    end if;
    if not public.is_child_of_household(new.household_id) then
       -- We check if the assignee is a child of THIS household specifically
       if not exists (
         select 1 from public.household_members hm
         where hm.household_id = new.household_id
           and hm.user_id = new.assignee_id
           and hm.role = 'child'
       ) then
         raise exception 'Chores can only be assigned to children of the same household';
       end if;
    else
       -- Redundant check logic simplified: ensure assignee is a child in the same household
       if not exists (
         select 1 from public.household_members hm
         where hm.household_id = new.household_id
           and hm.user_id = new.assignee_id
           and hm.role = 'child'
       ) then
         raise exception 'Chores can only be assigned to children of the same household';
       end if;
    end if;
  elsif tg_op = 'UPDATE' then
    -- Prevent changing household
    if new.household_id != old.household_id then
      raise exception 'Cannot move chores between households';
    end if;

    -- R4: If approved, nothing changes
    if old.status = 'approved' then
      raise exception 'Approved chores cannot be modified';
    end if;

    if public.is_parent_of_household(new.household_id) then
      -- Parents can edit/delete unapproved chores, but cannot change assignee to non-child or title/points arbitrarily?
      -- Rule R2 says "edit and delete their household's chores that are not yet approved".
      -- Rule R3 implies children can ONLY change status to done.
      -- So parents can change anything on unapproved chores?
      -- Let's restrict assignee to still be a child of the household if changed.
      if new.assignee_id != old.assignee_id then
        if not exists (
          select 1 from public.household_members hm
          where hm.household_id = new.household_id
            and hm.user_id = new.assignee_id
            and hm.role = 'child'
        ) then
          raise exception 'Chores can only be assigned to children of the same household';
        end if;
      end if;

      -- Parents can approve
      -- Parents can change title, points, status (to approved or back to todo/done)
    elsif public.is_child_of_household(new.household_id) then
      -- R3: Children can mark their own todo chores as done, and nothing else.
      if new.assignee_id != auth.uid() then
        raise exception 'Children can only modify their own chores';
      end if;
      if old.status != 'todo' then
        raise exception 'Children can only mark todo chores as done';
      end if;
      if new.status != 'done' then
        raise exception 'Children can only change status to done';
      end if;
      -- Ensure no other fields changed
      if new.title != old.title or new.points != old.points or new.assignee_id != old.assignee_id or new.household_id != old.household_id then
        raise exception 'Children cannot change title, points, or assignee';
      end if;
    else
      raise exception 'Unauthorized action';
    end if;
  end if;

  return new;
end;
$$;

create trigger trigger_chore_permissions
before insert or update on public.chores
for each row execute procedure public.check_chore_household_membership();

-- R6: Anonymous visitors cannot see or change anything. 
-- Policies below only apply to authenticated users. 
-- No policies for 'anon' role means default deny.

-- R1: Household members can see their household
