on public.household_members
for select
to authenticated
using (public.is_member_of_household(household_id));

-- R5: Nobody can change memberships
-- No insert/update/delete policies for household_members implies deny.

-- R1: Household members can see all chores of their household
create policy "Members can view their household chores"
on public.chores
for select
to authenticated
using (public.is_member_of_household(household_id));

-- R2: Parents can create chores
create policy "Parents can create chores"
on public.chores
for insert
to authenticated
with check (public.is_parent_of_household(household_id));

-- R2 & R3 & R4: Update logic handled by trigger, but we need a policy to allow the update attempt
-- The trigger will enforce the specific field-level rules.
-- We allow update if the user is a member (parent or child) and the chore is not approved (checked in trigger mostly, but let's add a baseline check).
-- Actually, the trigger raises exceptions. The policy just needs to let the right people attempt the update.
-- R4: Once approved, nobody can change. The trigger handles this.
-- Policy: Allow update if member of household. Specifics enforced by trigger.
create policy "Members can update chores (subject to restrictions)"
on public.chores
for update
to authenticated
using (public.is_member_of_household(household_id))
with check (public.is_member_of_household(household_id));

-- R2: Parents can delete unapproved chores.
-- R4: Approved chores cannot be deleted.
-- We need a trigger for delete as well to check approval status.
create function public.check_chore_delete_permissions()
returns trigger
language plpgsql
security definer
as $$
begin
  if old.status = 'approved' then
    raise exception 'Approved chores cannot be deleted';
  end if;

  if not public.is_parent_of_household(old.household_id) then
    raise exception 'Only parents can delete chores';
  end if;

  return old;
end;
$$;

