alter table public.patients enable row level security;
alter table public.care_team enable row level security;
alter table public.lab_results enable row level security;

create function public.is_doctor_for_patient(target_patient_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.care_team ct
    where ct.patient_id = target_patient_id
      and ct.doctor_id = auth.uid()
  );
$$ language sql security definer;

create function public.is_patient_owner(target_patient_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.patients p
    where p.id = target_patient_id
      and p.user_id = auth.uid()
  );
$$ language sql security definer;

create function public.is_result_released(res public.lab_results)
returns boolean as $$
  select res.released_at is not null and res.released_at <= now();
$$ language sql immutable;

-- Patients: SELECT own patient row
create policy "patients_select_own" on public.patients
  for select
  to authenticated
  using (user_id = auth.uid());

-- Doctors: SELECT patient rows they are assigned to
create policy "doctors_select_assigned_patients" on public.patients
  for select
  to authenticated
  using (public.is_doctor_for_patient(id));

-- Care Team: SELECT own assignments (patients see their team, doctors see their patients)
create policy "care_team_select_visible" on public.care_team
  for select
  to authenticated
  using (
    doctor_id = auth.uid()
    OR
    exists (
      select 1 from public.patients p
      where p.id = care_team.patient_id and p.user_id = auth.uid()
    )
  );

-- Lab Results: Patients see released results for their own patients
create policy "patients_select_released_results" on public.lab_results
  for select
  to authenticated
  using (
    public.is_patient_owner(patient_id)
    AND public.is_result_released(row(public.lab_results.*))
  );

-- Lab Results: Doctors see all results for their assigned patients
create policy "doctors_select_all_assigned_results" on public.lab_results
  for select
  to authenticated
  using (public.is_doctor_for_patient(patient_id));

-- Lab Results: Doctors can insert results for assigned patients
create policy "doctors_insert_results" on public.lab_results
  for insert
  to authenticated
  with check (public.is_doctor_for_patient(patient_id));

-- Lab Results: Doctors can update results only if not yet released
create policy "doctors_update_unreleased_results" on public.lab_results
  for update
  to authenticated
  using (
    public.is_doctor_for_patient(patient_id)
    AND NOT public.is_result_released(row(public.lab_results.*))
  )
  with check (
    public.is_doctor_for_patient(patient_id)
    AND NOT public.is_result_released(row(public.lab_results.*))
  );

-- Prevent updates/deletes on patients and care_team for all authenticated users (R4)
create policy "patients_no_modifications" on public.patients
  for all
  to authenticated
  using (false)
  with check (false);

create policy "care_team_no_modifications" on public.care_team
  for all
  to authenticated
  using (false)
  with check (false);

-- Prevent deletes on lab_results for all authenticated users (R4)
create policy "lab_results_no_deletes" on public.lab_results
  for delete
  to authenticated
  using (false);

-- Prevent patients from inserting/updating lab results (handled by doctor-only policies, but explicit deny for clarity if roles were mixed)
-- Note: The existing doctor policies already restrict insert/update to doctors. 
-- However, to ensure patients cannot update even if they somehow matched a check (they won't due to is_doctor_for_patient), 
-- the logic holds. R5 is handled by 'to authenticated' clauses; anon has no policies so default deny applies.

-- Grants for authenticated users to access tables (policies handle row filtering)
grant usage on schema public to authenticated;
grant select on public.patients to authenticated;
grant select on public.care_team to authenticated;
grant select, insert, update on public.lab_results to authenticated;

-- Revoke direct modification on patients/care_team to ensure only service_role or specific triggers could ever change them if needed later
revoke insert, update, delete on public.patients from authenticated;
revoke insert, update, delete on public.care_team from authenticated;
revoke delete on public.lab_results from authenticated;
