$$ language sql security definer;

-- Helper function to get current user ID
create or replace function public.current_user_id()
returns uuid as $$
  select auth.uid();
$$ language sql security definer;

-- Auctions Policies
-- R1: Signed-in users can see every auction
create policy "authenticated_users_view_auctions"
on public.auctions
for select
to authenticated
using (true);

-- R5: Anonymous visitors cannot see anything (default deny, but explicit for clarity if needed, though RLS defaults to deny)
-- No policy for anon on auctions means they cannot select.

-- R2: Nobody can create, change or delete auctions directly
-- No INSERT, UPDATE, DELETE policies created for auctions ensures this for app users.
-- Service role bypasses RLS automatically.

-- Bids Policies
-- R1: Bidders can see their own bids
create policy "bidders_view_own_bids"
on public.bids
for select
to authenticated
using (bidder_id = public.current_user_id());

-- R1: Sellers can see every bid on their auctions
