on public.bids
for select
to authenticated
using (
  exists (
    select 1 from public.auctions a
    where a.id = bids.auction_id
    and a.seller_id = public.current_user_id()
  )
);

-- R2: Nobody can create, change or delete bids directly
-- No INSERT, UPDATE, DELETE policies created for bids ensures this for app users.

-- Place Bid Function (R3, R4, R5)
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_auction record;
  v_min_bid numeric;
  v_current_user uuid;
begin
  -- R4: Check if caller is signed in
  if not public.is_authenticated() then
    raise exception 'Authentication required';
  end if;

  v_current_user := public.current_user_id();

  -- R4: Check if auction exists and fetch details
  select * into v_auction
  from public.auctions
  where id = p_auction_id;

  if not found then
    raise exception 'Auction not found';
  end if;

  -- R4: Check if auction has ended
  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- R4: Check if caller is the seller
  if v_auction.seller_id = v_current_user then
    raise exception 'Sellers cannot bid on their own auctions';
  end if;

  -- Calculate minimum required bid
  if v_auction.highest_bid is null then
    v_min_bid := v_auction.starting_price;
  else
    v_min_bid := v_auction.highest_bid + v_auction.min_increment;
  end if;

  -- R4: Check if amount is too low
  if p_amount < v_min_bid then
    raise exception 'Bid amount too low. Minimum required: %', v_min_bid;
  end if;

  -- R3: Record the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_current_user, p_amount, now());

  -- R3: Update the auction's highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_current_user
  where id = p_auction_id;

  return p_amount;
end;
$$;

