create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_sign_order integer;
  v_user_id uuid;
  v_max_order integer;
  v_signed_count integer;
  v_total_recipients integer;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope not found';
  end if;

  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  select sign_order into v_sign_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = v_user_id;

  if v_sign_order is null then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = v_user_id and signed_at is not null
  ) then
    raise exception 'Recipient has already signed';
  end if;

  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
    and sign_order < v_sign_order
    and signed_at is null
  ) then
    raise exception 'Previous recipients have not signed yet';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_user_id;

  select count(*) into v_total_recipients from public.envelope_recipients where envelope_id = p_envelope_id;
  select count(*) into v_signed_count from public.envelope_recipients where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed_count = v_total_recipients then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    return 'completed';
  end if;

  return 'sent';
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_sender_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select status, sender_id into v_status, v_sender_id
  from public.envelopes
  where id = p_envelope_id;

  if v_status is null then
    raise exception 'Envelope not found';
  end if;

  if auth.uid() != v_sender_id then
    raise exception 'Only the sender can void this envelope';
  end if;

  if v_status != 'sent' then
    raise exception 'Only envelopes in sent status can be voided';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;
  return 'voided';
end;
$$;

