-- Helper function to check if current user is sender of an envelope
create or replace function public.is_envelope_sender(p_envelope_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.envelopes e
    where e.id = p_envelope_id and e.sender_id = auth.uid()
  );
$$ language sql security definer stable;

-- Helper function to check if current user is a recipient of an envelope
create or replace function public.is_envelope_recipient(p_envelope_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.envelope_recipients er
    where er.envelope_id = p_envelope_id and er.user_id = auth.uid()
  );
$$ language sql security definer stable;

-- Helper function to get the sign_order of the current user for an envelope
create or replace function public.get_user_sign_order(p_envelope_id bigint)
returns integer as $$
  select er.sign_order
  from public.envelope_recipients er
  where er.envelope_id = p_envelope_id and er.user_id = auth.uid();
$$ language sql security definer stable;

-- Helper function to check if all previous recipients have signed
create or replace function public.are_previous_recipients_signed(p_envelope_id bigint, p_user_order integer)
returns boolean as $$
  select not exists (
    select 1
    from public.envelope_recipients er
    where er.envelope_id = p_envelope_id
      and er.sign_order < p_user_order
      and er.signed_at is null
  );
$$ language sql security definer stable;

-- Helper function to check if all recipients have signed
create or replace function public.are_all_recipients_signed(p_envelope_id bigint)
returns boolean as $$
  select not exists (
    select 1
    from public.envelope_recipients er
    where er.envelope_id = p_envelope_id
      and er.signed_at is null
  );
$$ language sql security definer stable;

-- R1: Senders and recipients can see their envelopes
create policy "senders_and_recipients_can_view_envelopes"
on public.envelopes
for select
to authenticated
using (
  public.is_envelope_sender(id) or public.is_envelope_recipient(id)
);

-- R1: Senders and recipients can see recipient lists of their envelopes
create policy "senders_and_recipients_can_view_recipients"
on public.envelope_recipients
for select
to authenticated
using (
  public.is_envelope_sender(envelope_id) or public.is_envelope_recipient(envelope_id)
);

-- R2: Nobody can create, change or delete envelopes directly
create policy "no_direct_envelope_modifications"
on public.envelopes
for all
to authenticated
using (false)
with check (false);

-- R2: Nobody can create, change or delete recipients directly
create policy "no_direct_recipient_modifications"
on public.envelope_recipients
for all
to authenticated
using (false)
with check (false);

-- R5: Anonymous visitors cannot see or change anything (explicit deny for anon)
create policy "anon_no_access_envelopes"
on public.envelopes
for all
to anon
using (false)
with check (false);

create policy "anon_no_access_recipients"
on public.envelope_recipients
for all
to anon
using (false)
with check (false);

-- R3: sign_envelope function
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text as $$
declare
  v_status text;
  v_user_order integer;
  v_current_status text;
begin
  -- Get current envelope status
  select e.status into v_current_status
  from public.envelopes e
  where e.id = p_envelope_id;

  -- Check if envelope exists and is in 'sent' status
  if v_current_status is null then
    raise exception 'Envelope not found';
  end if;

  if v_current_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Check if caller is a recipient
  if not public.is_envelope_recipient(p_envelope_id) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- Get caller's sign order
  v_user_order := public.get_user_sign_order(p_envelope_id);

  -- Check if caller has already signed
  if exists (
    select 1 from public.envelope_recipients er
    where er.envelope_id = p_envelope_id
      and er.user_id = auth.uid()
      and er.signed_at is not null
  ) then
    raise exception 'Recipient has already signed';
  end if;

  -- Check if all previous recipients have signed
  if not public.are_previous_recipients_signed(p_envelope_id, v_user_order) then
    raise exception 'Previous recipients have not signed yet';
  end if;

  -- Record the signature
  update public.envelope_recipients er
  set signed_at = now()
  where er.envelope_id = p_envelope_id
    and er.user_id = auth.uid();

  -- Check if all recipients have signed and update status if so
  if public.are_all_recipients_signed(p_envelope_id) then
    update public.envelopes e
    set status = 'completed'
    where e.id = p_envelope_id;
