alter table public.board_notes enable row level security;

-- Helper function to check if user is a moderator
create or replace function public.is_moderator()
returns boolean as $$
begin
  return (
    select exists (
      select 1
      from auth.users
      where id = auth.uid()
      and raw_user_meta_data->>'role' = 'moderator'
    )
  );
end;
$$ language plpgsql security definer;

-- R1: Anyone can read every note
create policy "Anyone can read notes"
on public.board_notes
for select
using (true);

-- R2 & R4: Signed-in users can insert as themselves; anonymous cannot
create policy "Authenticated users can insert their own notes"
on public.board_notes
for insert
with check (
  auth.role() = 'authenticated'
  and author_id = auth.uid()
);

-- R2: Authors can update their own notes (but not is_pinned per R3)
create policy "Authors can update their own notes"
on public.board_notes
for update
using (
  auth.role() = 'authenticated'
  and author_id = auth.uid()
)
with check (
  auth.role() = 'authenticated'
  and author_id = auth.uid()
  and is_pinned = (select is_pinned from public.board_notes where id = board_notes.id)
);

-- R3: Only moderators can update is_pinned
create policy "Moderators can pin/unpin notes"
on public.board_notes
for update
using (
  auth.role() = 'authenticated'
  and public.is_moderator()
)
with check (
  auth.role() = 'authenticated'
  and public.is_moderator()
);

-- R2: Authors can delete their own notes
create policy "Authors can delete their own notes"
on public.board_notes
for delete
using (
  auth.role() = 'authenticated'
  and author_id = auth.uid()
);

-- Grant necessary permissions to roles
grant usage on schema public to anon, authenticated;
grant select on public.board_notes to anon, authenticated;
grant insert on public.board_notes to authenticated;
grant update on public.board_notes to authenticated;
grant delete on public.board_notes to authenticated;
grant execute on function public.is_moderator() to authenticated;
