alter table public.board_notes enable row level security;

-- Helper function to check if user is a moderator
create or replace function public.is_moderator()
returns boolean as $$
  select exists (
    select 1 from auth.users u
    where u.id = auth.uid()
    and (u.raw_user_meta_data->>'role') = 'moderator'
  );
$$ language sql security definer;

-- R1: Anyone can read every note
create policy "allow_public_read" on public.board_notes
  for select
  to anon, authenticated
  using (true);

-- R2 & R4: Signed-in users can insert as themselves; anonymous cannot
create policy "allow_authenticated_insert" on public.board_notes
  for insert
  to authenticated
  with check (author_id = auth.uid());

-- R2: Authors can update their own notes (but not is_pinned - handled by trigger)
create policy "allow_author_update" on public.board_notes
  for update
  to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

-- R2: Authors can delete their own notes
create policy "allow_author_delete" on public.board_notes
  for delete
  to authenticated
  using (author_id = auth.uid());

-- R3: Moderators can update is_pinned; trigger prevents others from changing it
create policy "allow_moderator_pin" on public.board_notes
  for update
  to authenticated
  using (public.is_moderator())
  with check (public.is_moderator());

-- Trigger to enforce R3: prevent non-moderators from changing is_pinned
create or replace function public.enforce_pin_restrictions()
returns trigger as $$
begin
  if not public.is_moderator() then
    new.is_pinned := old.is_pinned;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trg_enforce_pin_restrictions
  before update on public.board_notes
  for each row
  execute function public.enforce_pin_restrictions();

-- Revoke all from anon except select
revoke insert, update, delete on public.board_notes from anon;

-- Grant necessary permissions to authenticated
grant insert (author_id, body, color) on public.board_notes to authenticated;
grant update (body, color) on public.board_notes to authenticated;
grant delete on public.board_notes to authenticated;

