-- Helper function to check if current user is a mechanic of a specific garage
create or replace function public.is_mechanic_of_garage(target_garage_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.mechanics
    where garage_id = target_garage_id
    and user_id = auth.uid()
  );
$$ language sql security definer;

