create or replace function public.is_job_customer(target_job_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.jobs
    where id = target_job_id
    and customer_id = auth.uid()
  );
$$ language sql security definer;

-- GARAGES POLICIES
-- R1: Signed-in users can see the list of garages
create policy "authenticated_users_view_garages"
on public.garages
for select
to authenticated
using (true);

-- R5/R6: No inserts/updates/deletes for garages by app users (service_role bypasses automatically)
create policy "no_modifications_garages"
on public.garages
for all
to authenticated
using (false)
with check (false);

-- MECHANICS POLICIES
-- R1: Mechanics can see their own membership (implied for join logic if needed, though mostly used via functions)
create policy "mechanics_view_own_membership"
on public.mechanics
for select
to authenticated
using (user_id = auth.uid());

-- R5: No modifications to mechanics table via app
create policy "no_modifications_mechanics"
on public.mechanics
for all
to authenticated
using (false)
with check (false);

-- JOBS POLICIES

-- R1: Customers see their own jobs; Mechanics see every job of their garage
create policy "view_jobs_customers_and_mechanics"
on public.jobs
for select
to authenticated
using (
  customer_id = auth.uid() 
  OR 
  is_mechanic_of_garage(garage_id)
);

-- R2: Mechanics can open jobs (insert) for their garage, status must be 'quoted'
create policy "mechanics_insert_jobs"
on public.jobs
for insert
to authenticated
with check (
  is_mechanic_of_garage(garage_id)
  AND status = 'quoted'
);

-- R2, R3, R4: Update rules
-- Complex logic split into checks for WITH CHECK (new state) and USING (old state/permissions)
create policy "update_jobs_restricted"
on public.jobs
for update
to authenticated
using (
  -- Allow update if user is mechanic of the garage OR the customer
  (is_mechanic_of_garage(garage_id) OR customer_id = auth.uid())
)
with check (
  -- R5: Garage ID cannot change
  garage_id = (select garage_id from public.jobs where id = id) -- Correlated subquery refers to OLD row in WITH CHECK context effectively via exclusion, but strictly we compare NEW.garage_id to OLD.garage_id. 
  -- In Supabase/Postgres WITH CHECK, 'id' refers to the NEW row. We need to ensure garage_id didn't change.
  -- Since we can't easily access OLD in WITH CHECK directly without a trigger or complex syntax, we rely on the fact that 
  -- the primary key 'id' is immutable and garage_id is NOT NULL. 
  -- However, to strictly enforce "nobody can change garages", we compare NEW.garage_id to the existing record.
  garage_id = (SELECT j.garage_id FROM public.jobs j WHERE j.id = jobs.id) -- This is tricky in WITH CHECK. 
  -- Better approach for immutability of garage_id: Ensure NEW.garage_id equals the value currently in the table for this ID.
  -- Actually, standard pattern: NEW.garage_id = OLD.garage_id. In WITH CHECK clause, we don't have OLD alias.
  -- We must assume the application doesn't send garage_id on update, or we use a trigger to enforce immutability.
  -- Given constraints "Output exactly one sql block... create function, create trigger", let's add a trigger for immutability of garage_id and status logic if too complex.
  -- But let's try to fit logic in policy first. 
  -- To enforce garage_id immutability in policy: 
  -- We can't reference OLD in WITH CHECK. So we will use a BEFORE UPDATE trigger for strict field immutability (R5) and complex state transitions.
  -- For the policy, we focus on WHO can update and high-level state rules.
  true 
);

-- Drop the previous generic update policy and replace with specific logic + Trigger for strict rules
drop policy if exists "update_jobs_restricted" on public.jobs;

-- Policy to allow mechanics to update jobs (R2: change quote while quoted, R4: move status approved->in_progress->done)
create policy "mechanics_update_jobs"
on public.jobs
for update
to authenticated
using (
  is_mechanic_of_garage(garage_id)
)
with check (
  -- R5: Mechanics cannot change garage_id (enforced by trigger too, but good here)
  garage_id = (select garage_id from public.jobs where id = jobs.id) -- Still problematic in pure SQL policy without OLD. 
  -- Relying on Trigger for field immutability.

  -- R2: If status was 'quoted', mechanic can update quote_amount and keep status 'quoted' OR move to 'approved'? 
  -- No, R3 says ONLY customer can approve. So mechanic cannot set status to 'approved'.
  -- Mechanic can change quote_amount ONLY if status remains 'quoted'.
  -- Mechanic can change status from 'approved' to 'in_progress', or 'in_progress' to 'done'.
  -- Mechanic cannot change quote_amount if status is not 'quoted'.

  CASE 
    WHEN (select status from public.jobs where id = jobs.id) = 'quoted' THEN
      -- Old status was quoted
      -- Mechanic can change quote_amount, but status must remain 'quoted' (cannot approve)
      (status = 'quoted')
      -- quote_amount can be anything (R2: change a quote)
    WHEN (select status from public.jobs where id = jobs.id) = 'approved' THEN
      -- Old status was approved
      -- Mechanic can move to 'in_progress'. Cannot change quote_amount.
      (status = 'in_progress' AND quote_amount = (select quote_amount from public.jobs where id = jobs.id))
    WHEN (select status from public.jobs where id = jobs.id) = 'in_progress' THEN
      -- Old status was in_progress
      -- Mechanic can move to 'done'. Cannot change quote_amount.
      (status = 'done' AND quote_amount = (select quote_amount from public.jobs where id = jobs.id))
    ELSE
      false
  END
);

-- Policy to allow customers to update jobs (R3: approve quoted job, cannot change anything else)
create policy "customers_approve_jobs"
on public.jobs
for update
to authenticated
using (
  customer_id = auth.uid()
)
with check (
  -- R3: Only approve a quoted job
  (select status from public.jobs where id = jobs.id) = 'quoted'
  AND status = 'approved'
  -- R3: Approving cannot change anything else, including amount
  AND quote_amount = (select quote_amount from public.jobs where id = jobs.id)
  AND garage_id = (select garage_id from public.jobs where id = jobs.id)
  AND vehicle = (select vehicle from public.jobs where id = jobs.id)
);

-- Trigger to enforce strict immutability of garage_id and prevent illegal state transitions that might slip through 
-- or handle the "OLD" value comparison for garage_id which is hard in WITH CHECK.
create or replace function public.enforce_job_immutability_and_transitions()
returns trigger as $$
begin
  -- R5: Nobody can change garage_id
  if new.garage_id is distinct from old.garage_id then
    raise exception 'Cannot change garage_id of a job';
  end if;

  -- R5: Nobody can change customer_id or vehicle arbitrarily? 
  -- Rules say: "approving cannot change anything else". 
  -- Mechanics changing quote: implied they can change quote_amount. 
  -- Can they change vehicle? Rules don't explicitly say mechanics can edit vehicle, only "change a quote".
  -- Safest to lock vehicle and customer_id always.
  if new.customer_id is distinct from old.customer_id then
    raise exception 'Cannot change customer_id';
  end if;

  if new.vehicle is distinct from old.vehicle then
    raise exception 'Cannot change vehicle details';
  end if;

  -- Re-enforce state machine logic strictly with OLD/NEW access
  -- R2: Mechanic updating quoted job
  if old.status = 'quoted' and auth.uid() in (select user_id from mechanics where garage_id = old.garage_id) then
    if new.status != 'quoted' then
      raise exception 'Mechanics cannot change status of a quoted job (only customers can approve)';
    end if;
    -- quote_amount can change, others checked above
  end if;

  -- R3: Customer approving
  if old.status = 'quoted' and old.customer_id = auth.uid() then
    if new.status != 'approved' then
      raise exception 'Customers can only approve quoted jobs, not change to other statuses';
    end if;
    if new.quote_amount != old.quote_amount then
      raise exception 'Customers cannot change quote amount when approving';
    end if;
  end if;

  -- R4: Mechanic moving approved -> in_progress -> done
  if old.status = 'approved' and auth.uid() in (select user_id from mechanics where garage_id = old.garage_id) then
    if new.status != 'in_progress' then
      raise exception 'Mechanics can only move approved jobs to in_progress';
    end if;
    if new.quote_amount != old.quote_amount then
      raise exception 'Cannot change quote amount after approval';
    end if;
  end if;

  if old.status = 'in_progress' and auth.uid() in (select user_id from mechanics where garage_id = old.garage_id) then
    if new.status != 'done' then
      raise exception 'Mechanics can only move in_progress jobs to done';
    end if;
    if new.quote_amount != old.quote_amount then
      raise exception 'Cannot change quote amount after approval';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;

create trigger trigger_enforce_job_rules
before update on public.jobs
for each row
execute function public.enforce_job_immutability_and_transitions();

-- R6: Anonymous visitors cannot see or change anything (Default deny, but explicit for clarity if any wide policies existed)
-- Since we only created policies for 'authenticated', 'anon' has no access by default.

-- Grants
grant usage on schema public to anon, authenticated;
grant select on public.garages to authenticated;
grant select on public.mechanics to authenticated;
grant select on public.jobs to authenticated;
grant insert on public.jobs to authenticated;
grant update on public.jobs to authenticated;

-- Revoke direct access to tables from anon explicitly (redundant but safe)
revoke all on public.garages from anon;
revoke all on public.mechanics from anon;
revoke all on public.jobs from anon;
