create function public.check_membership_tier(required_tier text)
returns boolean as $$
declare
  user_tier text;
  valid_date date;
begin
  select m.tier, m.valid_until into user_tier, valid_date
  from public.memberships m
  where m.user_id = auth.uid();

  if user_tier is null then
    return false;
  end if;

  if valid_date < current_date then
    return false;
  end if;

  if required_tier = 'premium' and user_tier != 'premium' then
    return false;
  end if;

  return true;
end;
$$ language plpgsql security definer;

create function public.check_booking_limit()
returns boolean as $$
declare
  booking_count int;
begin
  select count(*) into booking_count
  from public.bookings b
  where b.user_id = auth.uid()
    and b.day >= current_date;

  return booking_count < 3;
end;
