```sql
-- Enable RLS on all tables
alter table public.org_admins enable row level security;
alter table public.devices enable row level security;
alter table public.device_commands enable row level security;

-- Helper function to check if current user is an admin of the given org_id
create or replace function public.is_org_admin(target_org_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.org_admins
    where org_id = target_org_id
      and user_id = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if current user is assigned to the given device
create or replace function public.is_device_assigned(target_device_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.devices
    where id = target_device_id
      and assigned_to = auth.uid()
  );
end;
$$ language plpgsql security definer;

-- =============================================================================
-- ORG_ADMINS POLICIES
-- Rule R4: Nobody can change org_admins through the app.
-- Rule R1/R2: Admins need to be able to read their own membership to verify permissions logic elsewhere if needed, 
-- but strictly speaking, the app logic usually checks this table. 
-- We allow admins to see rows where they are the admin. No inserts/updates/deletes via RLS (handled by R4).
-- =============================================================================

-- Select: Admins can see their own admin record (useful for UI state)
create policy "org_admins_select_self"
on public.org_admins
for select
to authenticated
using (user_id = auth.uid());

-- No insert/update/delete policies for org_admins (implicit deny for authenticated, R4)

-- =============================================================================
-- DEVICES POLICIES
-- Rule R1: Employees see assigned devices. Admins see all org devices.
-- Rule R4: No changes to devices.
-- =============================================================================

-- Select: Assigned users OR Org Admins
create policy "devices_select_assigned_or_admin"
on public.devices
for select
to authenticated
using (
  assigned_to = auth.uid() 
  OR 
  is_org_admin(org_id)
);

-- No insert/update/delete policies for devices (implicit deny, R4)

-- =============================================================================
-- DEVICE_COMMANDS POLICIES
-- Rule R1: See commands for assigned devices or org devices (if admin).
-- Rule R2: Admins can issue any command to org devices.
-- Rule R3: Employees can issue locate/lock to assigned devices. No wipe.
-- Rule R4: No updates or deletes.
-- Rule R5: Anonymous denied (default).
-- =============================================================================

-- Select: Commands linked to devices the user can see (assigned or admin)
create policy "device_commands_select_visible"
on public.device_commands
for select
to authenticated
using (
  exists (
    select 1 from public.devices d
    where d.id = device_commands.device_id
      and (d.assigned_to = auth.uid() OR is_org_admin(d.org_id))
  )
);

-- Insert: 
-- Case A: Admin issuing any command to org device
-- Case B: Employee issuing locate/lock to assigned device
create policy "device_commands_insert_rules"
on public.device_commands
for insert
to authenticated
with check (
  -- Ensure the issuer is the current user (prevents impersonation)
  issued_by = auth.uid()
  AND
  (
    -- Admin Path: Can issue any command to any device in their org
    (
      is_org_admin((select org_id from public.devices where id = device_commands.device_id))
      AND command in ('locate', 'lock', 'wipe')
    )
    OR
    -- Employee Path: Can only issue locate/lock to devices assigned to them
    (
      is_device_assigned(device_commands.device_id)
      AND command in ('locate', 'lock')
    )
  )
);

-- No update/delete policies for device_commands (implicit deny, R4)

-- =============================================================================
-- GRANTS
-- Ensure authenticated users have usage on the helper functions and basic table access
-- (Policies restrict the rows, grants allow the operation type)
-- =============================================================================

grant usage on schema public to authenticated;
grant execute on function public.is_org_admin(bigint) to authenticated;
grant execute on function public.is_device_assigned(bigint) to authenticated;

-- Grants for table operations (Policies will filter rows)
grant select on public.org_admins to authenticated;
grant select on public.devices to authenticated;
grant select, insert on public.device_commands to authenticated;

-- Revoke everything from anon (R5)
revoke all on table public.org_admins from anon;
revoke all on table public.devices from anon;
revoke all on table public.device_commands from anon;
revoke execute on function public.is_org_admin(bigint) from anon;
revoke execute on function public.is_device_assigned(bigint) from anon;
