```sql
-- Enable RLS
alter table public.org_members enable row level security;
alter table public.records enable row level security;
alter table public.audit_log enable row level security;

-- Helper function to check if current user is admin of an org
create or replace function public.is_org_admin(target_org_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.org_members
    where org_id = target_org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$ language sql security definer stable;

-- Helper function to get user's orgs
create or replace function public.get_user_orgs()
returns setof bigint as $$
  select org_id from public.org_members where user_id = auth.uid();
$$ language sql security definer stable;

-- R1: Members see own memberships; Admins see deleted records, members don't
create policy "members_view_own_membership" on public.org_members
  for select
  using (user_id = auth.uid());

create policy "members_view_non_deleted_records" on public.records
  for select
  using (
    org_id in (select get_user_orgs())
    and (deleted_at is null or public.is_org_admin(org_id))
  );

-- R2: Members create/edit non-deleted; Only admins delete (soft)
create policy "members_insert_records" on public.records
  for insert
  with check (
    org_id in (select get_user_orgs())
    and deleted_at is null
  );

create policy "members_update_non_deleted_records" on public.records
  for update
  using (
    org_id in (select get_user_orgs())
    and deleted_at is null
  )
  with check (
    org_id in (select get_user_orgs())
    and deleted_at is null
  );

create policy "admins_soft_delete_records" on public.records
  for update
  using (
    public.is_org_admin(org_id)
  )
  with check (
    public.is_org_admin(org_id)
  );

-- R3: Audit log triggers
create or replace function public.handle_record_audit()
returns trigger as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'insert', auth.uid());
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'update', auth.uid());
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger audit_record_insert
  after insert on public.records
  for each row execute procedure public.handle_record_audit();

create trigger audit_record_update
  after update on public.records
  for each row execute procedure public.handle_record_audit();

-- R3 & R4: Audit log access (no direct writes, admins read only)
create policy "no_direct_audit_modifications" on public.audit_log
  for all
  using (false)
  with check (false);

create policy "admins_view_audit_log" on public.audit_log
  for select
  using (
    exists (
      select 1 from public.records r
      where r.id = record_id
        and public.is_org_admin(r.org_id)
    )
  );

-- R5: Restore record function
create or replace function public.restore_record(p_record_id bigint)
returns void as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
begin
  -- Get record info
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  if not found then
    raise exception 'Record not found';
  end if;

  -- Check if caller is admin
  if not public.is_org_admin(v_org_id) then
    raise exception 'Only admins can restore records';
  end if;

  -- Check if record is deleted
  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check if within 30 days
  if v_deleted_at < (now() - interval '30 days') then
    raise exception 'Record was deleted more than 30 days ago';
  end if;

  -- Restore
  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$ language plpgsql security definer;

-- R6: Revoke all from anon, ensure authenticated can access
revoke all on table public.org_members from anon;
revoke all on table public.records from anon;
