    values (new.id, 'update', auth.uid());
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trigger_record_audit
after insert or update on public.records
for each row execute procedure public.handle_record_audit();

-- R5: Restore function
create or replace function public.restore_record(p_record_id bigint)
returns void as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
begin
  -- Get record details
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  if not found then
    raise exception 'Record not found';
  end if;

  -- Check if caller is admin of the org
  if not public.is_org_admin(v_org_id) then
    raise exception 'Only admins can restore records';
  end if;

  -- Check if record is deleted
  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check if deleted within last 30 days
  if v_deleted_at < (now() - interval '30 days') then
    raise exception 'Record was deleted more than 30 days ago and cannot be restored';
  end if;

  -- Perform restore
  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$ language plpgsql security definer;

-- R6: Anonymous visitors cannot see or change anything.
-- This is handled by the policies above which rely on auth.uid() being present in org_members.
-- If auth.uid() is null (anon), `user_id = auth.uid()` and `org_id in (select ...)` will return false/null, denying access.
-- Service role bypasses RLS automatically.

-- Grants
grant usage on schema public to anon, authenticated;
grant select on public.org_members to authenticated;
grant select, insert, update on public.records to authenticated;
grant select on public.audit_log to authenticated;
grant execute on function public.is_org_admin(bigint) to authenticated;
grant execute on function public.get_user_org_ids() to authenticated;
grant execute on function public.restore_record(bigint) to authenticated;

-- Revoke direct access to audit_log modification
revoke insert, update, delete on public.audit_log from authenticated, anon;
```

```sql
-- Enable RLS on all tables
alter table public.org_members enable row level security;
alter table public.records enable row level security;
alter table public.audit_log enable row level security;

-- Helper function to check if current user is an admin of a specific org
create or replace function public.is_org_admin(target_org_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.org_members
    where org_id = target_org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$ language sql security definer stable;

-- Helper function to get the user's org IDs
create or replace function public.get_user_org_ids()
returns setof bigint as $$
  select org_id from public.org_members where user_id = auth.uid();
$$ language sql security definer stable;

-- R1: Members can see their own memberships
create policy "view_own_membership" on public.org_members
  for select
  to authenticated
  using (user_id = auth.uid());

-- R1: Members see non-deleted records in their org; Admins see all (including deleted) in their org
create policy "view_records_members" on public.records
  for select
  to authenticated
  using (
    org_id in (select get_user_org_ids())
    and (
      role = 'admin' 
      or (deleted_at is null)
    )
  );
-- Note: The above policy needs to check the user's role dynamically. 
-- Let's rewrite using the helper function logic directly in the policy for clarity and correctness.
drop policy if exists "view_records_members" on public.records;

create policy "view_records_org_members" on public.records
  for select
  to authenticated
  using (
    org_id in (select get_user_org_ids())
    and (
      public.is_org_admin(org_id) 
      or deleted_at is null
    )
  );

-- R2: Members can create records in their organization
create policy "insert_records_members" on public.records
  for insert
  to authenticated
  with check (
    org_id in (select get_user_org_ids())
    and deleted_at is null
  );

-- R2: Members can edit non-deleted records in their org. 
-- Only admins can set deleted_at (soft delete). 
-- This is handled by separating update logic: 
-- General update allowed for members on non-deleted rows.
-- Restricting the ability to set deleted_at only to admins is tricky in a single policy.
-- We allow updates if:
-- 1. User is member/admin of org AND row is not deleted (standard edit)
-- 2. User is admin of org AND they are setting deleted_at (soft delete)
-- However, R2 says "Only admins can delete". It implies members cannot modify a row to make it deleted.
-- But members can edit other fields.
-- Let's enforce: Update allowed if user belongs to org.
-- Additional check: If deleted_at is being changed from null to not-null, user MUST be admin.
-- If deleted_at is already not-null, only admin can update (to undo? No, undo is via RPC. So maybe no updates to deleted rows except by admin? R2 says "edit its records that are not deleted").
-- So: Members can update if row is not deleted. Admins can update even if deleted (maybe to restore metadata? Or just strictly R2: "edit its records that are not deleted" applies to members, admins can delete. Can admins edit deleted records? R2 doesn't explicitly forbid admins editing deleted records, but implies their special power is deleting. Let's assume admins can edit anything in their org, members only non-deleted).

drop policy if exists "update_records_members" on public.records;
create policy "update_records_org_members" on public.records
  for update
  to authenticated
  using (
    org_id in (select get_user_org_ids())
    and (
      -- If row is not deleted, any member/admin can update
      (deleted_at is null)
      or
      -- If row is deleted, only admin can update (though business logic might restrict this further, R2 says members edit non-deleted)
      (public.is_org_admin(org_id))
    )
  )
  with check (
    org_id in (select get_user_org_ids())
    and (
      -- Prevent members from undeleting or modifying deleted rows improperly
      -- If the NEW row is deleted (deleted_at is not null), the user MUST be an admin
      (new.deleted_at is not null and public.is_org_admin(org_id))
      or
      -- If the NEW row is not deleted, the user must be a member/admin, 
      -- BUT if the OLD row was deleted, only admin could have made this change (covered by USING clause effectively, but let's be safe)
      -- Actually, simpler: If user is not admin, they cannot touch a row that is currently deleted (USING) 
      -- and they cannot create a state where it is deleted (WITH CHECK).
      (new.deleted_at is null and old.deleted_at is null)
      or
      -- Allow admin to do anything
      (public.is_org_admin(org_id))
    )
  );

-- Refining the update policy for strictness based on R2:
-- "Members can ... edit its records that are not deleted." -> Members cannot update if old.deleted_at is not null.
-- "Only admins can delete" -> Members cannot set new.deleted_at to not null.
-- Admins can delete (set deleted_at). Can admins edit other fields of deleted records? Not specified, but usually yes.
-- Let's simplify:
-- USING: User belongs to org. If user is not admin, row must not be deleted.
-- WITH CHECK: User belongs to org. If user is not admin, new row must not be deleted.
drop policy if exists "update_records_org_members" on public.records;
create policy "update_records_org_members" on public.records
  for update
  to authenticated
  using (
    org_id in (select get_user_org_ids())
    and (
      public.is_org_admin(org_id) 
      or deleted_at is null
    )
  )
  with check (
    org_id in (select get_user_org_ids())
    and (
      public.is_org_admin(org_id) 
      or new.deleted_at is null
    )
  );

-- R3 & R6: Nobody can create, change, or delete audit rows directly.
-- We will handle insertion via Trigger. No policies for INSERT/UPDATE/DELETE for users on audit_log.
-- R4: Admins can read audit rows of their org's records; members cannot.
create policy "view_audit_log_admins" on public.audit_log
  for select
  to authenticated
  using (
    exists (
      select 1 from public.records r
      join public.org_members om on r.org_id = om.org_id
      where r.id = audit_log.record_id
        and om.user_id = auth.uid()
        and om.role = 'admin'
    )
  );

-- R3: Trigger to add audit log on insert/update of records
create or replace function public.handle_record_audit()
returns trigger as $$
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'insert', auth.uid());
  elsif tg_op = 'UPDATE' then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'update', auth.uid());
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger trigger_record_audit
after insert or update on public.records
for each row execute procedure public.handle_record_audit();

-- R5: restore_record function
create or replace function public.restore_record(p_record_id bigint)
returns void as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
begin
  -- Get record info
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  -- Check if record exists
  if v_org_id is null then
    raise exception 'Record not found';
  end if;

  -- Check if caller is admin of the org
  if not public.is_org_admin(v_org_id) then
    raise exception 'Only admins can restore records';
  end if;

  -- Check if record is deleted
  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check if deleted within last 30 days
  if v_deleted_at < (now() - interval '30 days') then
    raise exception 'Record was deleted more than 30 days ago and cannot be restored';
  end if;

  -- Perform restore
  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$ language plpgsql security definer;

-- Grants
-- Revoke all on audit_log from authenticated to ensure no direct writes (RLS handles reads, but explicit revoke for safety on writes if any other policy exists)
revoke insert, update, delete on public.audit_log from authenticated;
revoke insert, update, delete on public.audit_log from anon;

-- Ensure anon has no access anywhere (RLS policies are only for authenticated, so anon is blocked by default if no policy, but explicit revoke on tables is good practice if they had defaults)
-- Actually, RLS denies all by default if no policy matches. Since we only created policies for 'authenticated', 'anon' is already blocked.
-- Just ensure service_role bypasses (it does by default in Supabase).

-- Grant execute on restore_record to authenticated (admins will pass internal checks)
grant execute on function public.restore_record(bigint) to authenticated;
revoke execute on function public.restore_record(bigint) from anon;
```

