```sql
alter table public.residents enable row level security;
alter table public.permits enable row level security;
alter table public.hoa_admins enable row level security;

create function public.is_hoa_admin() returns boolean as $$
  select exists (
    select 1 from public.hoa_admins where user_id = auth.uid()
  );
$$ language sql security definer stable;

create function public.is_resident_of_unit(p_unit_id bigint) returns boolean as $$
  select exists (
    select 1 from public.residents where unit_id = p_unit_id and user_id = auth.uid()
  );
$$ language sql security definer stable;

create function public.count_active_permits(p_unit_id bigint) returns integer as $$
  select count(*)::integer
  from public.permits
  where unit_id = p_unit_id
    and revoked = false
    and valid_until >= current_date;
$$ language sql security definer stable;

-- HOA Admins: Full read access to permits
create policy "hoa_admins_select_permits" on public.permits
  for select
  to authenticated
  using (public.is_hoa_admin());

-- Residents: Select permits for their own unit
create policy "residents_select_permits" on public.permits
  for select
  to authenticated
  using (public.is_resident_of_unit(unit_id));

-- Residents: Insert permits for their own unit with constraints
create policy "residents_insert_permits" on public.permits
  for insert
  to authenticated
  with check (
    public.is_resident_of_unit(unit_id)
    and revoked = false
    and valid_until <= (current_date + interval '365 days')
    and valid_until >= current_date
    and public.count_active_permits(unit_id) < 2
  );

-- Residents: Update plate only on their own unit's permits
create policy "residents_update_plate_permits" on public.permits
  for update
  to authenticated
  using (
    public.is_resident_of_unit(unit_id)
    and revoked = false
    and valid_until >= current_date
  )
  with check (
    public.is_resident_of_unit(unit_id)
    and revoked = false
    and valid_until = (select valid_until from public.permits where id = permits.id)
    and revoked = (select revoked from public.permits where id = permits.id)
  );

-- HOA Admins: Revoke permits (set revoked = true only)
create policy "hoa_admins_revoke_permits" on public.permits
  for update
  to authenticated
  using (public.is_hoa_admin())
  with check (
    public.is_hoa_admin()
    and id = permits.id
    and unit_id = (select unit_id from public.permits where id = permits.id)
    and plate = (select plate from public.permits where id = permits.id)
    and valid_until = (select valid_until from public.permits where id = permits.id)
    and (revoked = true or revoked = (select revoked from public.permits where id = permits.id))
  );

-- Residents: Select their own residence rows
create policy "residents_select_residents" on public.residents
  for select
  to authenticated
  using (user_id = auth.uid());

-- HOA Admins: Select all residence rows
create policy "hoa_admins_select_residents" on public.residents
  for select
  to authenticated
  using (public.is_hoa_admin());

-- HOA Admins: Select all admins
create policy "hoa_admins_select_hoa_admins" on public.hoa_admins
  for select
  to authenticated
  using (true);

-- Deny all modifications to residents and hoa_admins for authenticated users
create policy "deny_residents_modifications" on public.residents
  for all
  to authenticated
  using (false)
  with check (false);

create policy "deny_hoa_admins_modifications" on public.hoa_admins
  for all
  to authenticated
  using (false)
  with check (false);

-- Deny anonymous access to everything
create policy "deny_anon_permits" on public.permits for all to anon using (false) with check (false);
create policy "deny_anon_residents" on public.residents for all to anon using (false) with check (false);
create policy "deny_anon_hoa_admins" on public.hoa_admins for all to anon using (false) with check (false);

-- Grant usage to authenticated role
grant usage on schema public to authenticated;
grant select on public.residents to authenticated;
grant select on public.hoa_admins to authenticated;
grant select, insert, update on public.permits to authenticated;
```

