alter table public.bookings enable row level security;
alter table public.booking_messages enable row level security;

create function public.is_booking_participant(target_booking_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.bookings b
    where b.id = target_booking_id
      and (b.student_id = auth.uid() or b.tutor_id = auth.uid())
  );
$$ language sql security definer;

create function public.is_booking_confirmed(target_booking_id bigint)
returns boolean as $$
  select status = 'confirmed'
  from public.bookings
  where id = target_booking_id;
$$ language sql security definer;

-- R1 & R4: Students and tutors can see their own bookings. Anonymous sees nothing.
create policy "participants_can_view_bookings"
on public.bookings
for select
to authenticated
using (
  student_id = auth.uid() or tutor_id = auth.uid()
);

-- R4: Nobody can create or change bookings through the app (service_role bypasses automatically)
create policy "no_booking_inserts"
on public.bookings
for insert
to authenticated
with check (false);

create policy "no_booking_updates"
on public.bookings
for update
to authenticated
using (false);

create policy "no_booking_deletes"
on public.bookings
for delete
to authenticated
using (false);

-- R1: Participants can see messages on their bookings
create policy "participants_can_view_messages"
on public.booking_messages
for select
to authenticated
using (
  public.is_booking_participant(booking_id)
);

-- R2: Participants can insert messages only if booking is confirmed and sender is themselves
create policy "participants_can_insert_messages"
on public.booking_messages
for insert
to authenticated
with check (
  public.is_booking_participant(booking_id)
  and public.is_booking_confirmed(booking_id)
  and sender_id = auth.uid()
);

-- R3: Senders can delete their own messages
create policy "senders_can_delete_messages"
on public.booking_messages
for delete
to authenticated
using (
  sender_id = auth.uid()
);

-- R3: Nobody can edit messages
create policy "no_message_updates"
on public.booking_messages
for update
to authenticated
using (false);

-- Explicitly revoke access from anon to ensure R4
revoke all on table public.bookings from anon;
revoke all on table public.booking_messages from anon;
