create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
)
returns integer
language plpgsql
security definer
as $$
declare
  v_source_qty integer;
  v_dest_qty integer;
  v_remaining integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  if p_from = p_to then
    raise exception 'Source and destination warehouses cannot be the same';
  end if;

  if not exists (select 1 from public.warehouses where id = p_from) then
    raise exception 'Source warehouse does not exist';
  end if;

  if not exists (select 1 from public.warehouses where id = p_to) then
    raise exception 'Destination warehouse does not exist';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  select qty into v_source_qty
  from public.stock
  where warehouse_id = p_from and sku = p_sku
  for update;

  if v_source_qty is null or v_source_qty < p_qty then
    raise exception 'Insufficient stock at source warehouse';
  end if;

  select qty into v_dest_qty
  from public.stock
  where warehouse_id = p_to and sku = p_sku
  for update;

  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  v_remaining := v_source_qty - p_qty;

  if v_dest_qty is null then
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  else
    update public.stock
    set qty = qty + p_qty
    where warehouse_id = p_to and sku = p_sku;
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  return v_remaining;
end;
$$;

