-- R3: set_member_role function
create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text as $$
declare
  v_caller_role text;
  v_target_role text;
begin
  -- Validate role input
  if p_role not in ('admin', 'member') then
    raise exception 'Invalid role specified';
  end if;

  -- Get caller's role in the org
  select role into v_caller_role
  from public.org_members
  where org_id = p_org_id and user_id = auth.uid();

  -- Check if caller is owner or admin
  if v_caller_role is null or v_caller_role not in ('owner', 'admin') then
    raise exception 'Caller is not an owner or admin of this organization';
  end if;

  -- Get target's current role
  select role into v_target_role
  from public.org_members
  where org_id = p_org_id and user_id = p_user_id;

  -- Check if target exists in the organization
  if v_target_role is null then
    raise exception 'Target user is not a member of this organization';
  end if;

  -- Check if target is trying to modify themselves
  if p_user_id = auth.uid() then
    raise exception 'Cannot modify your own role via this function';
  end if;

  -- Check if target is an owner (cannot change owner role)
  if v_target_role = 'owner' then
    raise exception 'Cannot modify the role of an owner';
  end if;

  -- Perform the update
  update public.org_members
  set role = p_role
  where org_id = p_org_id and user_id = p_user_id;

  return p_role;
end;
